   404	// Only the local branch counts — remote-tracking presence is not enough.
   405	// If only the remote-tracking ref exists, a subsequent WriteCommitted creates
   406	// a brand-new orphan local branch with an empty tree, which would clobber
   407	// the remote on push.
   408	//
   409	// Fast path: check local refs directly — no network. If missing, trigger the
   410	// metadata fetch fallback chain used by `entire resume` (which advances the
   411	// local ref on success) and re-check. Returns a possibly-freshly-opened repo
   412	// handle so go-git sees any newly fetched packfiles.
   413	func ensureCheckpointAvailable(ctx, logCtx context.Context, repo *git.Repository, refs cpkg.CommittedRefs, checkpointID id.CheckpointID, isExistingCheckpoint bool) (*git.Repository, error) {
   414		if !isExistingCheckpoint {
   415			return repo, nil
