   458	// checkpointPresentLocally reports whether the checkpoint already exists at
   459	// Primary locally. Reads target Primary directly, not refs.Read, because this
   460	// asks what the next write would find, not what readers see. A missing local
   461	// ref is reported as absent; the caller is responsible for any remote refresh.
   462	func checkpointPresentLocally(ctx context.Context, repo *git.Repository, refs cpkg.CommittedRefs, checkpointID id.CheckpointID) (bool, error) {
   463		if _, err := repo.Reference(refs.Primary, true); err != nil {
   464			return false, nil //nolint:nilerr // Missing ref is the "absent" signal, not an error.
   465		}
