   635	// resolveAndValidateTranscript finds the transcript file for a session, searching alternative
   636	// project directories if needed.
   637	func resolveAndValidateTranscript(ctx context.Context, sessionID string, ag agent.Agent) (string, error) {
   638		transcriptPath, err := resolveTranscriptPath(ctx, sessionID, ag)
   639		if err != nil {
   640			return "", fmt.Errorf("failed to resolve transcript path: %w", err)
   641		}
   642		// Only call PrepareTranscript when the file already exists — it flushes
   643		// in-progress writes, but can't conjure a file that was never started.
   644		// This avoids agents like Cursor polling for 3s on non-existent files
   645		// during auto-detection.
   646		if _, statErr := os.Stat(transcriptPath); statErr == nil {
   647			if preparer, ok := agent.AsTranscriptPreparer(ag); ok {
   648				if prepErr := preparer.PrepareTranscript(ctx, transcriptPath); prepErr != nil {
   649					logging.Debug(ctx, "PrepareTranscript failed (best-effort)", "error", prepErr)
   650				}
   651			}
   652			return transcriptPath, nil
   653		}
   654		found, searchErr := searchTranscriptInProjectDirs(sessionID, ag)
   655		if searchErr == nil {
   656			logging.Info(ctx, "found transcript in alternative project directory", "path", found)
   657			return found, nil
   658		}
   659		logging.Debug(ctx, "fallback transcript search failed", "error", searchErr)
   660		return "", fmt.Errorf("transcript not found for agent %q with session %s; is the session ID correct?", ag.Name(), sessionID)
