   663	// detectAgentByTranscript tries all registered agents (except skip) to find one whose
   664	// transcript resolution succeeds for the given session ID.
   665	func detectAgentByTranscript(ctx context.Context, sessionID string, skip types.AgentName) (agent.Agent, string, error) {
   666		for _, name := range agent.List() {
   667			if name == skip {
   668				continue
