   684	// promptAmendCommit shows the last commit and asks whether to amend it with the checkpoint trailer.
   685	// When force is true, it amends without prompting.
   686	func promptAmendCommit(ctx context.Context, w io.Writer, headCommit *object.Commit, checkpointIDStr string, force bool) error {
   687		shortHash := headCommit.Hash.String()[:7]
   688		subject := strings.SplitN(headCommit.Message, "\n", 2)[0]
   689	
   690		// Skip amending if this exact checkpoint ID is already in the commit.
   691		for _, existing := range trailers.ParseAllCheckpoints(headCommit.Message) {
   692			if existing.String() == checkpointIDStr {
   693				fmt.Fprintf(w, "Commit %s already has Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
   694				return nil
   695			}
   696		}
   697	
   698		fmt.Fprintf(w, "\nLast commit: %s %s\n", shortHash, subject)
   699	
   700		amend := true
   701		if !force {
   702			if !interactive.CanPromptInteractively() {
   703				// Non-interactive: can't prompt, print trailer for manual use.
   704				fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
   705				return nil
   706			}
   707			form := NewAccessibleForm(
   708				huh.NewGroup(
   709					huh.NewConfirm().
   710						Title("Amend the last commit in this branch?").
   711						Affirmative("Y").
   712						Negative("n").
   713						Value(&amend),
   714				),
   715			)
   716			if err := form.Run(); err != nil {
   717				return fmt.Errorf("prompt failed: %w", err)
   718			}
   719		}
   720	
   721		if !amend {
   722			fmt.Fprintf(w, "\nCopy to your commit message to attach:\n\n  Entire-Checkpoint: %s\n", checkpointIDStr)
   723			return nil
   724		}
   725	
   726		newMessage := trailers.AppendCheckpointTrailer(headCommit.Message, checkpointIDStr)
   727	
   728		cmd := exec.CommandContext(ctx, "git", "commit", "--amend", "--only", "-m", newMessage)
   729		if output, err := cmd.CombinedOutput(); err != nil {
   730			return fmt.Errorf("failed to amend commit: %w\n%s", err, output)
   731		}
   732	
   733		fmt.Fprintf(w, "Amended commit %s with Entire-Checkpoint: %s\n", shortHash, checkpointIDStr)
   734		return nil
   735	}

