   376	// emitContextInjection writes ag's native context-injection payload to stdout
   377	// when ag injects at event.Type, trails are enabled for the repo on the API,
   378	// and this session has not been injected yet. Best-effort: an injection failure
   379	// never fails the hook.
   380	func emitContextInjection(ctx context.Context, ag agent.Agent, event *agent.Event) {
   381		injector, ok := agent.AsContextInjector(ag)
   382		if !ok || injector.InjectionEvent() != event.Type || event.SessionID == "" {
   383			return
   384		}
   385		logCtx := logging.WithAgent(logging.WithComponent(ctx, "lifecycle"), ag.Name())
   386	
   387		// Decide once per session, recorded on the session state itself (not a
   388		// separate marker file). Winning the check-and-set means this turn owns the
   389		// decision. trailsEnabledForRepo only reads clone-local cached enablement;
   390		// the API refresh happens earlier on `entire enable`, outside the prompt path.
   391		// Marking "decided" before checking the cache means a missing/stale false
   392		// cache fails closed (no hint for this session) rather than retrying/spamming.
   393		mutated := false
   394		mutErr := strategy.MutateSessionState(ctx, event.SessionID, func(state *strategy.SessionState) error {
   395			if state.ContextInjectionDecided {
   396				return strategy.ErrMutationSkip
   397			}
   398			// Review/investigate sessions are task-specific and don't need the branch
   399			// trail pointer; skip without marking decided so normal sessions keep the
   400			// usual first-turn behavior.
   401			if state.Kind != "" {
   402				return strategy.ErrMutationSkip
   403			}
   404			state.ContextInjectionDecided = true
   405			mutated = true
   406			return nil
   407		})
   408		if mutErr != nil && !errors.Is(mutErr, strategy.ErrStateNotFound) {
   409			logging.Warn(logCtx, "failed to record context injection decision",
   410				slog.String("error", mutErr.Error()))
   411			return
   412		}
   413		// Only proceed after the state mutation was persisted. If saving the updated
   414		// state failed, mutErr was non-nil above and we returned without injecting,
   415		// leaving a later turn free to retry safely.
   416		won := mutErr == nil && mutated
   417		if !won {
   418			return // already decided for this session, skipped kind, or no session state yet
   419		}
   420	
   421		// Only advertise trails when they're literally enabled for this repo on the API.
   422		if !trailsEnabledForRepo(ctx) {
   423			return
   424		}
   425	
   426		payload, err := injector.RenderContextInjection(agent.ContextInjection{Text: entireTrailContextInjection()})
   427		if err != nil {
   428			logging.Warn(logCtx, "failed to render context injection",
   429				slog.String("error", err.Error()))
   430			return
   431		}
   432		if len(payload) == 0 {
   433			return
   434		}
