   227	func gitHookCommand(cmdPrefix, args string, warnMissing bool) string {
   228		invocation := fmt.Sprintf("%s hooks git %s", cmdPrefix, args)
   229		availableTest, ok := gitHookCommandAvailableTest(cmdPrefix)
   230		if !ok {
   231			return invocation
   232		}
   233	
   234		missingAction := ":"
   235		if warnMissing {
   236			missingAction = fmt.Sprintf("printf '%%s\\n' %s >&2 || :", shellQuote(missingEntireGitHookWarning))
   237		}
   238		return fmt.Sprintf("if %s; then %s; else %s; fi", availableTest, invocation, missingAction)
   239	}
