   241	func gitHookCommandAvailableTest(cmdPrefix string) (string, bool) {
   242		if cmdPrefix == "entire" {
   243			return "command -v entire >/dev/null 2>&1", true
   244		}
   245		if isWindowsAbsoluteHookCommand(cmdPrefix) {
   246			return fmt.Sprintf("[ -f %s ]", cmdPrefix), true
   247		}
   248		if strings.HasPrefix(cmdPrefix, "/") || strings.HasPrefix(cmdPrefix, "'/") {
   249			return fmt.Sprintf("[ -x %s ]", cmdPrefix), true
   250		}
   251		return "", false
   252	}
