   254	func isWindowsAbsoluteHookCommand(cmdPrefix string) bool {
   255		path := strings.TrimPrefix(cmdPrefix, "'")
   256		if len(path) < len("C:\\") || path[1] != ':' {
   257			return false
   258		}
   259		driveLetter := path[0]
   260		if (driveLetter < 'A' || driveLetter > 'Z') && (driveLetter < 'a' || driveLetter > 'z') {
   261			return false
   262		}
   263		return path[2] == '\\' || path[2] == '/'
   264	}
