   266	// InstallGitHook installs generic git hooks that delegate to `entire hook` commands.
   267	// These hooks work with any strategy - the strategy is determined at runtime.
   268	// If silent is true, no output is printed (except backup notifications, which always print).
   269	// localDev controls whether hooks use "go run" (true) or the "entire" binary (false).
   270	// absolutePath embeds the full binary path in hooks for GUI git clients.
   271	// Returns the number of hooks that were installed (0 if all already up to date).
   272	func InstallGitHook(ctx context.Context, silent, localDev, absolutePath bool) (int, error) {
   273		hooksDir, err := GetHooksDir(ctx)
   274		if err != nil {
   275			return 0, err
   276		}
   277	
   278		if err := os.MkdirAll(hooksDir, 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
   279			return 0, fmt.Errorf("failed to create hooks directory: %w", err)
   280		}
   281	
   282		cmdPrefix, err := hookCmdPrefix(localDev, absolutePath)
   283		if err != nil {
   284			return 0, err
   285		}
   286		specs := buildHookSpecs(cmdPrefix)
   287		installedCount := 0
   288	
   289		for _, spec := range specs {
   290			hookPath := filepath.Join(hooksDir, spec.name)
   291			backupPath := hookPath + backupSuffix
   292			backupExists := fileExists(backupPath)
   293	
   294			// Back up existing non-Entire hooks
   295			existing, existingErr := os.ReadFile(hookPath) //nolint:gosec // path is controlled
   296			if existingErr == nil && !strings.Contains(string(existing), entireHookMarker) {
   297				if !backupExists {
   298					if err := os.Rename(hookPath, backupPath); err != nil {
   299						return installedCount, fmt.Errorf("failed to back up %s: %w", spec.name, err)
   300					}
   301					fmt.Fprintf(os.Stderr, "[entire] Backed up existing %s to %s%s\n", spec.name, spec.name, backupSuffix)
   302				} else {
   303					fmt.Fprintf(os.Stderr, "[entire] Warning: replacing %s (backup %s%s already exists from a previous install)\n", spec.name, spec.name, backupSuffix)
   304				}
   305				backupExists = true
   306			}
   307	
   308			// Chain to backup if one exists
   309			content := spec.content
   310			if backupExists {
   311				content = generateChainedContent(spec.content, spec.name)
   312			}
   313	
   314			written, err := writeHookFile(hookPath, content)
   315			if err != nil {
   316				return installedCount, fmt.Errorf("failed to install %s hook: %w", spec.name, err)
   317			}
   318			if written {
   319				installedCount++
   320			}
   321		}
   322	
   323		if !silent {
   324			fmt.Println("✓ Installed git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
   325			fmt.Println("  Hooks delegate to the current strategy at runtime")
   326		}
   327	
   328		return installedCount, nil
   329	}
