   331	// writeHookFile writes a hook file if it doesn't exist or has different content.
   332	// Returns true if the file was written, false if it already had the same content.
   333	func writeHookFile(path, content string) (bool, error) {
   334		// Check if file already exists with same content
   335		existing, err := os.ReadFile(path) //nolint:gosec // path is controlled
   336		if err == nil && string(existing) == content {
   337			return false, nil // Already up to date
   338		}
   339	
   340		// Git hooks must be executable (0o755)
   341		if err := os.WriteFile(path, []byte(content), 0o755); err != nil { //nolint:gosec // Git hooks require executable permissions
   342			return false, fmt.Errorf("failed to write hook file %s: %w", path, err)
   343		}
   344		return true, nil
   345	}
