   347	// RemoveGitHook removes all Entire CLI git hooks from the repository.
   348	// If a .pre-entire backup exists, it is restored.
   349	// Returns the number of hooks removed.
   350	func RemoveGitHook(ctx context.Context) (int, error) {
   351		hooksDir, err := GetHooksDir(ctx)
   352		if err != nil {
   353			return 0, err
   354		}
   355	
   356		removed := 0
   357		var removeErrors []string
   358	
   359		for _, hook := range gitHookNames {
   360			hookPath := filepath.Join(hooksDir, hook)
   361			backupPath := hookPath + backupSuffix
   362	
   363			// Remove the hook if it contains our marker
   364			data, err := os.ReadFile(hookPath) //nolint:gosec // path is controlled
   365			hookIsOurs := err == nil && strings.Contains(string(data), entireHookMarker)
   366			hookExists := err == nil
   367	
   368			if hookIsOurs {
   369				if err := os.Remove(hookPath); err != nil {
   370					removeErrors = append(removeErrors, fmt.Sprintf("%s: %v", hook, err))
   371					continue
   372				}
   373				removed++
   374			}
   375	
   376			// Restore .pre-entire backup if it exists
   377			if fileExists(backupPath) {
   378				if hookExists && !hookIsOurs {
   379					// A non-Entire hook is present — don't overwrite it with the backup
   380					fmt.Fprintf(os.Stderr, "[entire] Warning: %s was modified since install; backup %s%s left in place\n", hook, hook, backupSuffix)
   381				} else {
   382					if err := os.Rename(backupPath, hookPath); err != nil {
   383						removeErrors = append(removeErrors, fmt.Sprintf("restore %s%s: %v", hook, backupSuffix, err))
   384					}
   385				}
   386			}
   387		}
   388	
   389		if len(removeErrors) > 0 {
   390			return removed, fmt.Errorf("failed to remove hooks: %s", strings.Join(removeErrors, "; "))
   391		}
   392		return removed, nil
   393	}
