   395	// generateChainedContent appends a chain call to the base hook content,
   396	// so the pre-existing hook (backed up to .pre-entire) is called after our hook.
   397	func generateChainedContent(baseContent, hookName string) string {
   398		if hookName == "post-rewrite" {
   399			return generatePostRewriteChainedContent(baseContent)
   400		}
   401	
   402		return baseContent + fmt.Sprintf(`%s
   403	_entire_hook_dir="$(dirname "$0")"
   404	if [ -x "$_entire_hook_dir/%s%s" ]; then
   405	    "$_entire_hook_dir/%s%s" "$@"
   406	fi
   407	`, chainComment, hookName, backupSuffix, hookName, backupSuffix)
   408	}
   409	
   410	func generatePostRewriteChainedContent(baseContent string) string {
   411		const original = `hooks git post-rewrite "$1" 2>/dev/null || true`
   412		const replacement = `hooks git post-rewrite "$1" < "$_entire_stdin" 2>/dev/null || true`
   413	
   414		replayPrefix := `#!/bin/sh
   415	_entire_stdin="$(mktemp "${TMPDIR:-/tmp}/entire-post-rewrite.XXXXXX")"
   416	cat > "$_entire_stdin"
   417	trap 'rm -f "$_entire_stdin"' EXIT
   418	`
   419	
   420		body := strings.TrimPrefix(baseContent, "#!/bin/sh\n")
   421		body = strings.Replace(body, original, replacement, 1)
   422	
   423		return replayPrefix + body + fmt.Sprintf(`
   424	%s
   425	_entire_hook_dir="$(dirname "$0")"
   426	if [ -x "$_entire_hook_dir/post-rewrite%s" ]; then
   427	    "$_entire_hook_dir/post-rewrite%s" "$@" < "$_entire_stdin"
   428	fi
   429	`, chainComment, backupSuffix, backupSuffix)
   430	}
