   432	// hookCmdPrefix returns the command prefix for hook scripts and warning messages.
   433	// Returns the scripts/entire-dev launcher when local_dev is enabled.
   434	// When absolutePath is true, resolves the full binary path via os.Executable()
   435	// and returns an error if resolution fails. This is needed for GUI git clients
   436	// (Xcode, Tower, etc.) that don't source shell profiles.
   437	func hookCmdPrefix(localDev, absolutePath bool) (string, error) {
   438		if localDev {
   439			return localDevHookCmdPrefix, nil
   440		}
   441		if absolutePath {
   442			exe, err := os.Executable()
   443			if err != nil {
   444				return "", fmt.Errorf("--absolute-git-hook-path: failed to resolve binary path: %w", err)
   445			}
   446			resolved, err := filepath.EvalSymlinks(exe)
   447			if err != nil {
   448				return "", fmt.Errorf("--absolute-git-hook-path: failed to resolve symlinks for %s: %w", exe, err)
   449			}
   450			return shellQuote(resolved), nil
   451		}
   452		return "entire", nil
   453	}
