const TOP_LEVEL_KEYS: readonly TopLevelFilterKey[] = [
  "prompts",
  "responses",
  "intermediateSteps",
  "checkpoints",
  "toolCalls",
]

/**
 * Index of the last content-bearing assistant message in a turn — the "final
 * response". Returns -1 when no message has content. Used to distinguish the
 * final response (kept on even when intermediateResponses is off) from the
 * intermediate ones.
 */
export function findFinalResponseIndex(messages: TranscriptMessage[]): number {
  let idx = -1
  for (let i = 0; i < messages.length; i++) {
    if (messages[i].content?.trim()) idx = i
  }
  return idx
}

// ── Visibility ───────────────────────────────────────────────────────────────

/** Any tool call in the list survives the current tool-call + category filters. */
export function hasVisibleToolCalls(
  toolCalls: ToolCall[] | undefined,
  filters: FilterState,
): boolean {
  if (!filters.toolCalls) return false
  return toolCalls?.some((tc) => filters.toolCategories[getToolCategory(tc.name)]) ?? false
}

/** True when applying `filters` would render at least one row from this item. */
export function isItemVisible(item: DisplayItem, filters: FilterState): boolean {
  if (item.kind === "checkpoint") return filters.checkpoints
  if (filters.prompts) {
    const content = item.userMessage?.content?.trim()
    const hasImages = (item.userMessage?.images?.length ?? 0) > 0
    const hasRuntimeTags = (item.userMessage?.runtimeTags?.length ?? 0) > 0
    const hasSkillInvocation = !!item.userMessage?.skillInvocation
    if (item.userMessage && (content || hasImages || hasRuntimeTags || hasSkillInvocation))
      return true
  }
  // Responses and tool calls are independent: a message with tool calls stays
  // visible (as a tools-only row) even when response text or intermediate
  // response text is filtered out.
  const finalIdx = findFinalResponseIndex(item.assistantMessages)
  for (let i = 0; i < item.assistantMessages.length; i++) {
    const m = item.assistantMessages[i]
    const isIntermediate = finalIdx >= 0 && i !== finalIdx
    const hasVisibleContent =
      filters.responses && !!m.content?.trim() && (!isIntermediate || filters.intermediateSteps)
    if (hasVisibleContent) return true
    if (hasVisibleToolCalls(m.toolCalls, filters)) return true
  }
  if (filters.checkpoints && item.checkpoints.length > 0) return true
  return false
}

/** Counts of messages and checkpoints bundled inside a display item. */
export function countItem(item: DisplayItem): { messages: number; checkpoints: number } {
  if (item.kind === "checkpoint") return { messages: 0, checkpoints: 1 }
  const userContent = item.userMessage?.content?.trim()
  const userImages = (item.userMessage?.images?.length ?? 0) > 0
  const userRuntimeTags = (item.userMessage?.runtimeTags?.length ?? 0) > 0
  const userSkillInvocation = !!item.userMessage?.skillInvocation
  const userCount =
    item.userMessage && (userContent || userImages || userRuntimeTags || userSkillInvocation)
      ? 1
      : 0
  return {
    messages: userCount + item.assistantMessages.length,
    checkpoints: item.checkpoints.length,
  }
}

// ── Reducers ─────────────────────────────────────────────────────────────────

/**
 * Pure state transition for toggling a top-level filter. Enforces two rules:
 * - Refuses to turn off the last remaining top-level filter so the timeline
 *   always has at least one rendered row type.
 * - Re-enabling Tool calls while every visible sub-category is off re-enables
 *   all categories, so the parent toggle produces a visible effect.
 *
 * `availableCategories` scopes the sub-category check to categories that
 * actually have calls in this session — the sidebar hides zero-count rows, so
 * their filter state doesn't matter and shouldn't keep the parent "on".
 */
export function toggleTopLevelFilter(
  prev: FilterState,
  key: TopLevelFilterKey,
  availableCategories: readonly ToolCategory[] = TOOL_CATEGORIES,
): FilterState {
  const topLevelOn = TOP_LEVEL_KEYS.filter((k) => prev[k]).length
  if (prev[key] && topLevelOn === 1) return prev
  const next: FilterState = { ...prev, [key]: !prev[key] }
  if (key === "toolCalls" && next.toolCalls) {
    const anyCategoryOn = availableCategories.some((c) => prev.toolCategories[c])
    if (!anyCategoryOn) next.toolCategories = ALL_TOOL_CATEGORIES_ON
  }
  return next
}

/**
 * Pure state transition for toggling a tool-call sub-category. Keeps the
 * parent Tool calls checkbox in sync in both directions:
 * - Turning the last *visible* sub-category off also unchecks the parent,
 *   since there'd be nothing left to render.
 * - Turning a sub-category on while the parent is off re-enables the parent,
 *   so the child click always has a visible effect — the UI no longer
 *   disables child rows when the parent is off.
 * - Turning a sub-category off while others remain on leaves the parent as it
 *   was, so a user who manually unchecked the parent can still tweak
 *   sub-categories without the parent flipping back on.
 *
 * `availableCategories` scopes the "any on" check to categories shown in the
 * sidebar (non-zero count) — filter state for hidden categories is irrelevant
 * and shouldn't keep the parent active.
 */
export function toggleToolCategoryFilter(
  prev: FilterState,
  prev: FilterState,
  category: ToolCategory,
  availableCategories: readonly ToolCategory[] = TOOL_CATEGORIES,
): FilterState {
  const turningOn = !prev.toolCategories[category]
  const toolCategories = { ...prev.toolCategories, [category]: turningOn }
  const anyCategoryOn = availableCategories.some((c) => toolCategories[c])
  const nextToolCalls = anyCategoryOn ? (turningOn ? true : prev.toolCalls) : false
  // Mirror toggleTopLevelFilter's last-filter guard: if this child toggle
  // would cascade Tool calls off and no other top-level filter is on, the
  // timeline would collapse to an all-hidden placeholder. Refuse the toggle.
  if (prev.toolCalls && !nextToolCalls) {
    const otherTopLevelOn = TOP_LEVEL_KEYS.some((k) => k !== "toolCalls" && prev[k])
    if (!otherTopLevelOn) return prev
  }
  return {
    ...prev,
    toolCategories,
    toolCalls: nextToolCalls,
  }
}

/**
 * Mirror of the guard inside `toggleToolCategoryFilter`: true when turning
 * `category` off would leave every top-level filter off (Tool calls is the sole
 * top-level filter on, and `category` is the only remaining visible
 * sub-category). The sidebar uses this to disable the checkbox — same pattern
 * as `lastActive` on top-level rows.
 */
export function isLastActiveToolCategory(
  filters: FilterState,
  category: ToolCategory,
  availableCategories: readonly ToolCategory[] = TOOL_CATEGORIES,
): boolean {
  if (!filters.toolCalls) return false
  if (!filters.toolCategories[category]) return false
  const otherTopLevelOn = TOP_LEVEL_KEYS.some((k) => k !== "toolCalls" && filters[k])
  if (otherTopLevelOn) return false
  const otherSubOn = availableCategories.some((c) => c !== category && filters.toolCategories[c])
  return !otherSubOn
}

// ── Transforms ───────────────────────────────────────────────────────────────

/**
 * Collapse runs of consecutive filter-hidden items into "N hidden" placeholder
 * rows. Leading, middle, and trailing runs are all preserved so the user can
 * see — and expand — hidden content anywhere on the timeline.
 */
export function computeRenderedItems(
  displayItems: DisplayItem[],
  filters: FilterState,
): RenderedItem[] {
  const out: RenderedItem[] = []
  let pending: { items: DisplayItem[]; messages: number; checkpoints: number } | null = null
  let hiddenIdx = 0

  const flush = () => {
    if (pending) {
      out.push({
        kind: "hidden",
        id: `hidden-${hiddenIdx++}`,
        items: pending.items,
        messages: pending.messages,
        checkpoints: pending.checkpoints,
      })
      pending = null
    }
  }

  for (const item of displayItems) {
    if (isItemVisible(item, filters)) {
      flush()
      if (item.kind === "checkpoint") {
        out.push({ kind: "checkpoint", checkpoint: item.checkpoint })
      } else {
        out.push({ kind: "turn", turn: item })
      }
    } else {
      const { messages, checkpoints } = countItem(item)
      if (!pending) pending = { items: [], messages: 0, checkpoints: 0 }
      pending.items.push(item)
      pending.messages += messages
      pending.checkpoints += checkpoints
    }
  }
  flush()
  return out
}

/**
 * Break a turn's hidden content down into the four buckets that drive the
 * per-turn placeholder label: fully suppressed messages, suppressed response
 * text (on rows still visible via tools), filtered-out tool calls, and hidden
 * inner checkpoints.
 */
export function computeTurnHiddenCounts(
  userMessage: TranscriptMessage | null,
  assistantMessages: TranscriptMessage[],
  checkpoints: SessionTimelineCheckpoint[],
  filters: FilterState,
): {
  hiddenMessages: number
  hiddenResponses: number
  hiddenToolCalls: number
  hiddenCheckpoints: number
  totalHidden: number
} {
  const userContent = userMessage?.content?.trim()
  const userImages = (userMessage?.images?.length ?? 0) > 0
  const userRuntimeTags = (userMessage?.runtimeTags?.length ?? 0) > 0
  const userSkillInvocation = !!userMessage?.skillInvocation
  let hiddenMessages =
    !filters.prompts &&
    !!userMessage &&
    !!(userContent || userImages || userRuntimeTags || userSkillInvocation)
      ? 1
      : 0
  let hiddenResponses = 0
  let hiddenToolCalls = 0
  const finalIdx = findFinalResponseIndex(assistantMessages)
  for (let i = 0; i < assistantMessages.length; i++) {
    const m = assistantMessages[i]
    const hasContent = !!m.content?.trim()
    const tools = m.toolCalls ?? []
    if (!hasContent && tools.length === 0) continue
    const isIntermediate = finalIdx >= 0 && i !== finalIdx
    const actuallyShowsContent =
      filters.responses && hasContent && (!isIntermediate || filters.intermediateSteps)
    const visibleToolCount = filters.toolCalls
      ? tools.filter((tc) => filters.toolCategories[getToolCategory(tc.name)]).length
      : 0
    const rowVisible = actuallyShowsContent || visibleToolCount > 0
    if (!rowVisible) {
      hiddenMessages++
    } else {
      if (hasContent && !actuallyShowsContent) hiddenResponses++
      hiddenToolCalls += tools.length - visibleToolCount
    }
  }
  const hiddenCheckpoints = filters.checkpoints ? 0 : checkpoints.length
  const totalHidden = hiddenMessages + hiddenResponses + hiddenToolCalls + hiddenCheckpoints
  return { hiddenMessages, hiddenResponses, hiddenToolCalls, hiddenCheckpoints, totalHidden }
}

/**
 * Number of tool calls that would render on the timeline right now — Tool
 * calls filter on AND the category is enabled. Drives the enabled/disabled
 * state of the "Expand all tool calls" sidebar action.
 */
export function computeVisibleToolCallCount(
  filters: FilterState,
  toolBreakdown: { category: ToolCategory; count: number }[],
): number {
  if (!filters.toolCalls) return 0
  return toolBreakdown.reduce(
    (sum, { category, count }) => sum + (filters.toolCategories[category] ? count : 0),
    0,
  )
}

