export function stripTranscript(content: string, parser?: TranscriptParser): string {
  if (parser?.strip) {
    return parser.strip(content)
  }

  const lines = content.split("\n")
  const result: string[] = []

  for (const line of lines) {
    const trimmed = line.trim()
    if (!trimmed) continue

    let parsed: Record<string, unknown>
    try {
