import type {
  TranscriptMessage,
  ToolCall,
  ToolCallResult,
  TranscriptRuntimeTag,
  ToolMixCategoryKey,
} from "../../types"
import { extractRuntimeTags, extractToolUseBlocks } from "./common"
import type { TranscriptParser, TranscriptParseResult } from "./types"
import { jsonlParseFrom } from "./types"

// Extract text and image content from message content (string or array of blocks)
interface ExtractedContent {
  text: string
  images: Array<{ mediaType: string; data: string }>
  hasToolResults: boolean
}

// Pattern for image references that Claude Code outputs when it "reads" an image.
// These are text markers like "[Image: source: /path/to/file.png]" - not actual image data.
// We strip these since the actual images are rendered from base64 content blocks.
const IMAGE_REFERENCE_PATTERN = /\[Image: source: [^\]]+\]/g

function extractTextContent(content: unknown): ExtractedContent {
  if (typeof content === "string") {
    return {
      text: content.replace(IMAGE_REFERENCE_PATTERN, "").trim(),
      images: [],
      hasToolResults: false,
    }
  }
  if (!Array.isArray(content)) {
    return { text: "", images: [], hasToolResults: false }
  }

  let text = ""
  const images: Array<{ mediaType: string; data: string }> = []
  let hasToolResults = false

  for (const block of content) {
    if (typeof block === "object" && block !== null) {
      const b = block as Record<string, unknown>
      if (b.type === "text") {
        text += (b.text as string) || ""
      } else if (b.type === "tool_result") {
        hasToolResults = true
      } else if (b.type === "image") {
        const source = b.source as Record<string, unknown> | undefined
        if (source?.type === "base64" && source.data && source.media_type) {
          images.push({
            mediaType: source.media_type as string,
            data: source.data as string,
          })
        }
      }
    }
  }
  // Strip image reference markers from text (see comment above)
  text = text.replace(IMAGE_REFERENCE_PATTERN, "").trim()

  return { text, images, hasToolResults }
}

// Extract tool_result metadata from a tool result record
function extractToolResultMetadata(parsed: Record<string, unknown>): ToolCallResult | undefined {
  const toolUseResult = parsed.toolUseResult as Record<string, unknown> | undefined
  if (!toolUseResult) return undefined

  const result: ToolCallResult = {
    type: (toolUseResult.type as "text" | "error") || "text",
  }

  // For file reads
  const file = toolUseResult.file as Record<string, unknown> | undefined
  if (file) {
    result.file = {
      filePath: file.filePath as string,
      numLines: file.numLines as number | undefined,
    }
  }

  // For errors
  if (toolUseResult.error) {
    result.error = toolUseResult.error as string
    result.type = "error"
  }

  // For AskUserQuestion - extract user's answers
  const answers = toolUseResult.answers as Record<string, string> | undefined
  if (answers) {
    result.answers = answers
  }

  return result
}

