export function computeRenderedItems(
  displayItems: DisplayItem[],
  filters: FilterState,
): RenderedItem[] {
  const out: RenderedItem[] = []
  let pending: { items: DisplayItem[]; messages: number; checkpoints: number } | null = null
  let hiddenIdx = 0

  const flush = () => {
    if (pending) {
      out.push({
        kind: "hidden",
        id: `hidden-${hiddenIdx++}`,
        items: pending.items,
        messages: pending.messages,
        checkpoints: pending.checkpoints,
      })
      pending = null
    }
