export function computeTurnHiddenCounts(
  userMessage: TranscriptMessage | null,
  assistantMessages: TranscriptMessage[],
  checkpoints: SessionTimelineCheckpoint[],
  filters: FilterState,
): {
  hiddenMessages: number
  hiddenResponses: number
  hiddenToolCalls: number
  hiddenCheckpoints: number
  totalHidden: number
} {
  const userContent = userMessage?.content?.trim()
  const userImages = (userMessage?.images?.length ?? 0) > 0
  const userRuntimeTags = (userMessage?.runtimeTags?.length ?? 0) > 0
  const userSkillInvocation = !!userMessage?.skillInvocation
  let hiddenMessages =
    !filters.prompts &&
    !!userMessage &&
    !!(userContent || userImages || userRuntimeTags || userSkillInvocation)
      ? 1
      : 0
  let hiddenResponses = 0
  let hiddenToolCalls = 0
  const finalIdx = findFinalResponseIndex(assistantMessages)
  for (let i = 0; i < assistantMessages.length; i++) {
    const m = assistantMessages[i]
    const hasContent = !!m.content?.trim()
    const tools = m.toolCalls ?? []
    if (!hasContent && tools.length === 0) continue
    const isIntermediate = finalIdx >= 0 && i !== finalIdx
    const actuallyShowsContent =
      filters.responses && hasContent && (!isIntermediate || filters.intermediateSteps)
    const visibleToolCount = filters.toolCalls
