import type { TranscriptMessage } from "@/domains/platform/checkpoints/api"

import type { SessionTimelineCheckpoint } from "./sessionFilters"

export type SessionScopeId = "whole-session" | `checkpoint:${number}`

export interface SessionScopeOption {
  id: SessionScopeId
  title: string
  subtitle?: string
}

function sortCheckpoints(checkpoints: SessionTimelineCheckpoint[]): SessionTimelineCheckpoint[] {
  return [...checkpoints].sort(
    (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
  )
}

export function getCheckpointIdForSessionScopeId(
  checkpoints: SessionTimelineCheckpoint[],
  scopeId: SessionScopeId,
): string | undefined {
  if (scopeId === "whole-session") return undefined
  const checkpointIndex = Number(scopeId.slice("checkpoint:".length))
  return sortCheckpoints(checkpoints)[checkpointIndex]?.checkpointId
}

export function getTimelineTargetIdForSessionScopeId(
  messages: TranscriptMessage[],
  checkpoints: SessionTimelineCheckpoint[],
  scopeId: SessionScopeId,
): string | undefined {
  if (scopeId === "whole-session") return undefined
  const checkpointId = getCheckpointIdForSessionScopeId(checkpoints, scopeId)
  if (!checkpointId) return undefined
  const scoped = scopeSessionTimeline(messages, checkpoints, scopeId)
  return scoped.messages.find((message) => message.role === "user")?.id ?? checkpointId
}

export function buildSessionScopeOptions(
  messages: TranscriptMessage[],
  checkpoints: SessionTimelineCheckpoint[],
): SessionScopeOption[] {
  const sorted = sortCheckpoints(checkpoints)
  return sorted.map((checkpoint, index) => {
    const scoped = scopeSessionTimeline(messages, sorted, `checkpoint:${index}`)
    const stepCount = scoped.messages.length
    const title = checkpoint.message || "Checkpoint"
    return {
      id: `checkpoint:${index}` as const,
      title,
      subtitle: `${checkpoint.checkpointId} ${stepCount} ${stepCount === 1 ? "step" : "steps"}`,
    }
  })
}

export function scopeSessionTimeline(
  messages: TranscriptMessage[],
  checkpoints: SessionTimelineCheckpoint[],
  scopeId: SessionScopeId,
): {
  messages: TranscriptMessage[]
  checkpoints: SessionTimelineCheckpoint[]
} {
  if (scopeId === "whole-session") {
    return { messages, checkpoints }
  }

  const checkpointIndex = Number(scopeId.slice("checkpoint:".length))
  const sortedCheckpoints = sortCheckpoints(checkpoints)
  const selectedCheckpoint = sortedCheckpoints[checkpointIndex]

  if (!selectedCheckpoint) {
    return { messages, checkpoints }
  }

  const previousCheckpoint = checkpointIndex > 0 ? sortedCheckpoints[checkpointIndex - 1] : null
  const startTime = previousCheckpoint ? new Date(previousCheckpoint.timestamp).getTime() : null
  const endTime = new Date(selectedCheckpoint.timestamp).getTime()
  const scopedMessages = messages.filter((message) => {
    const timestamp = new Date(message.timestamp).getTime()
    if (timestamp > endTime) return false
    if (startTime === null) return true
    return timestamp > startTime
  })
  const firstUserIndex = scopedMessages.findIndex((message) => message.role === "user")

  return {
    messages: firstUserIndex === -1 ? scopedMessages : scopedMessages.slice(firstUserIndex),
    checkpoints: [selectedCheckpoint],
  }
}

