import { useEffect, useRef, type DependencyList } from "react"

const TIMELINE_HASH_PREFIX = "#timeline-"
const HASH_TARGET_ATTR = "data-hash-target"

/**
 * `decodeURIComponent` throws on malformed percent-escapes (a user-pasted
 * truncated link); without this guard those crash anything that reads
 * `window.location.hash`. Empty hashes also return `null` so callers can use
 * a single `== null` check.
 */
export function decodeTimelineHashId(hash: string): string | null {
  if (!hash.startsWith(TIMELINE_HASH_PREFIX)) return null
  try {
    return decodeURIComponent(hash.slice(TIMELINE_HASH_PREFIX.length)) || null
  } catch {
    return null
  }
}

function clearTimelineHashTargets() {
  for (const el of document.querySelectorAll(`[${HASH_TARGET_ATTR}]`)) {
    el.removeAttribute(HASH_TARGET_ATTR)
  }
}

export function highlightTimelineTarget(targetId: string): HTMLElement | null {
  const element = document.getElementById(`timeline-${targetId}`)
  if (!element) return null
  if (element.getAttribute(HASH_TARGET_ATTR) === "true") return element
  clearTimelineHashTargets()
  element.setAttribute(HASH_TARGET_ATTR, "true")
  return element
}

function syncTimelineHashTarget({ clearWhenNoHash = true } = {}): HTMLElement | null {
  const id = decodeTimelineHashId(window.location.hash)
  if (id == null) {
    if (clearWhenNoHash) clearTimelineHashTargets()
    return null
  }
  return highlightTimelineTarget(id)
}

/**
 * Marks the element matching the current `#timeline-<id>` URL hash with a
 * `data-hash-target` attribute (so styles can react via `data-[hash-target=true]`)
 * and scrolls it into view. Reruns on `hashchange` and whenever any of the
 * passed `deps` change — pages pass their transcript-ready signal so
 * newly-rendered targets still get picked up.
 *
 * Uses a data attribute instead of `:target` because Chromium does not
 * re-evaluate `:target` reliably when the matching element is mounted after
 * the initial navigation, which is the common case here (transcript loads
 * after the route does).
 *
 * Scrolls at most once per hash. Once the user has been scrolled to a target,
 * later dep changes (transcript finishing, tab flips) won't yank them back —
 * only the highlight stays in sync.
 */
export function useScrollToTimelineHash(deps: DependencyList = []): void {
  const lastScrolledHash = useRef<string | null>(null)

  useEffect(() => {
    const element = syncTimelineHashTarget({ clearWhenNoHash: false })
    if (!element) return
    if (lastScrolledHash.current === window.location.hash) return
    lastScrolledHash.current = window.location.hash
    element.scrollIntoView({ behavior: "smooth", block: "start" })
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, deps)

  useEffect(() => {
    function onHashChange() {
      lastScrolledHash.current = null
      const element = syncTimelineHashTarget()
      if (!element) return
      lastScrolledHash.current = window.location.hash
      element.scrollIntoView({ behavior: "smooth", block: "start" })
    }
    window.addEventListener("hashchange", onHashChange)
    return () => window.removeEventListener("hashchange", onHashChange)
  }, [])
}

