export function getCheckpointSessionId(
  checkpoint: Pick<CheckpointInfo, "checkpointId">,
  session: Pick<CheckpointSessionInfo, "sessionId">,
): string {
  return session.sessionId || checkpoint.checkpointId
}

export function buildOrderedSessionMessages(
  sessions: Pick<SessionTranscript, "messages">[],
): TranscriptMessage[] {
  const seen = new Set<string>()
  const messages: TranscriptMessage[] = []

  for (const session of sessions) {
    for (const message of session.messages) {
      if (seen.has(message.id)) continue
      seen.add(message.id)
      messages.push(message)
    }
  }

  messages.sort((a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime())
  return messages
}

export function mapSessionEnvelopeCheckpoints(
  checkpoints: CompleteSessionTranscriptResponse["checkpoints"],
): SessionTimelineCheckpoint[] {
  return checkpoints.map((checkpoint) => ({
    checkpointId: checkpoint.checkpointId,
    commitSha: checkpoint.commitSha,
    message: checkpoint.message,
    additions: checkpoint.additions,
    deletions: checkpoint.deletions,
    filesChanged: checkpoint.filesChanged,
    timestamp: checkpoint.timestamp,
  }))
}

export function mapCheckpointInfoToTimelineCheckpoint(
  checkpoint: CheckpointInfo,
): SessionTimelineCheckpoint {
  return {
    checkpointId: checkpoint.checkpointId,
    commitSha: checkpoint.commitSha ?? checkpoint.checkpointId,
    message: checkpoint.commitSubject ?? checkpoint.commitMessage ?? "Checkpoint",
    additions: checkpoint.additions ?? 0,
    deletions: checkpoint.deletions ?? 0,
    filesChanged: checkpoint.filesChanged ?? checkpoint.fileStats?.length ?? 0,
    timestamp: checkpoint.commitDate ?? checkpoint.createdAt ?? "",
  }
}

export function buildCommitSessionTimelines(
  checkpoints: CheckpointInfo[],
  transcripts: CompleteCheckpointTranscriptResponse[],
): CommitSessionTimeline[] {
  const checkpointById = new Map(
    checkpoints.map((checkpoint) => [checkpoint.checkpointId, checkpoint]),
  )
  const sessions = new Map<string, CommitSessionTimelineAccumulator>()

  for (const checkpoint of checkpoints) {
    for (const sessionInfo of checkpoint.sessions) {
      const sessionId = getCheckpointSessionId(checkpoint, sessionInfo)
      const existing = sessions.get(sessionId)
      if (existing) {
        existing.steps += sessionInfo.steps
        if (!existing.prompt && sessionInfo.prompt) existing.prompt = sessionInfo.prompt
        if (!existing.model && sessionInfo.model) existing.model = sessionInfo.model
        const checkpointDate = checkpoint.commitDate ?? checkpoint.createdAt ?? null
        if (checkpointDate && (!existing.date || checkpointDate < existing.date))
          existing.date = checkpointDate
        continue
      }
      const checkpointDate = checkpoint.commitDate ?? checkpoint.createdAt ?? null

      sessions.set(sessionId, {
        sessionId,
        agent: sessionInfo.agent,
        prompt: sessionInfo.prompt,
        model: sessionInfo.model ?? null,
        steps: sessionInfo.steps,
        authorUsername: checkpoint.commitAuthorUsername,
        date: checkpointDate,
        transcriptSessions: [],
        checkpoints: [],
        checkpointIds: new Set(),
        tokenUsage: null,
      })
    }
  }

  for (const transcript of transcripts) {
    const checkpoint = checkpointById.get(transcript.checkpointId)
    const timelineCheckpoint = checkpoint ? mapCheckpointInfoToTimelineCheckpoint(checkpoint) : null

    for (const transcriptSession of transcript.sessions) {
      let session = sessions.get(transcriptSession.sessionId)
      if (!session) {
        session = {
          sessionId: transcriptSession.sessionId,
          agent: transcriptSession.agent,
          prompt: null,
          model: null,
          steps: transcriptSession.messages.length,
          authorUsername: checkpoint?.commitAuthorUsername ?? null,
          date: checkpoint?.commitDate ?? checkpoint?.createdAt ?? null,
          transcriptSessions: [],
          checkpoints: [],
          checkpointIds: new Set(),
          tokenUsage: null,
        }
        sessions.set(transcriptSession.sessionId, session)
      }

      session.transcriptSessions.push(transcriptSession)
      if (timelineCheckpoint && !session.checkpointIds.has(transcript.checkpointId)) {
        session.checkpointIds.add(transcript.checkpointId)
        session.checkpoints.push(timelineCheckpoint)
      }
      if (transcriptSession.tokenUsage) {
        if (!session.tokenUsage) {
          session.tokenUsage = { inputTokens: 0, outputTokens: 0 }
        }
        session.tokenUsage.inputTokens += transcriptSession.tokenUsage.inputTokens
        session.tokenUsage.outputTokens += transcriptSession.tokenUsage.outputTokens
      }
    }
  }

  return Array.from(sessions.values())
    .filter((session) => session.transcriptSessions.length > 0)
    .map((session) => ({
      sessionId: session.sessionId,
      agent: session.agent,
      prompt: session.prompt,
      model: session.model,
      steps: session.steps,
      authorUsername: session.authorUsername,
      date: session.date,
      messages: buildOrderedSessionMessages(session.transcriptSessions),
      checkpoints: session.checkpoints.sort(
        (a, b) => new Date(a.timestamp).getTime() - new Date(b.timestamp).getTime(),
      ),
      tokenUsage: session.tokenUsage ?? undefined,
    }))
}

