export function getSessionCheckpointTranscriptStart(
  sessions: SessionInfo[] | null,
  sessionIndex: number,
): number | null {
  if (sessions?.[sessionIndex]?.transcriptIdentifierAtStart) {
    return null
  }

  const offset = sessions?.[sessionIndex]?.checkpointTranscriptStart
  return typeof offset === "number" && offset > 0 ? offset : null
}

export function sliceTranscriptForStorage(
  content: string,
  parser: TranscriptParser,
  checkpointTranscriptStart: number | null,
): string {
  if (!checkpointTranscriptStart || checkpointTranscriptStart <= 0) {
    return content
  }

  const parserSlicedContent = parser.sliceForStorage?.(content, checkpointTranscriptStart)
  if (parserSlicedContent !== undefined) {
    return parserSlicedContent
  }

  if (parser.format === "jsonl") {
    return jsonlSliceForStorage(content, checkpointTranscriptStart)
  }

  try {
    const parsed = JSON.parse(content) as Record<string, unknown>
    if (!Array.isArray(parsed.messages)) {
      return content
    }

    const slicedMessages = parsed.messages.slice(checkpointTranscriptStart)
    if (slicedMessages.length === 0) return content

    return JSON.stringify({
      ...parsed,
      messages: slicedMessages,
    })
  } catch {
    return content
  }
}

