	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
)

type response struct {
	Status    string `json:"status"`
	SessionID string `json:"sessionId"`
	FromCache bool   `json:"from_cache"`
	Sessions  []struct {
		SessionID string `json:"sessionId"`
		Agent     string `json:"agent"`
		Messages  []struct {
			ID        string `json:"id"`
			Role      string `json:"role"`
			Content   string `json:"content"`
			ToolCalls []struct {
				Name  string `json:"name"`
				Input any    `json:"input"`
			} `json:"toolCalls"`
		} `json:"messages"`
	} `json:"sessions"`
	Checkpoints []struct {
		CheckpointID string `json:"checkpointId"`
		CommitSha    string `json:"commitSha"`
		Message      string `json:"message"`
		Timestamp    string `json:"timestamp"`
	} `json:"checkpoints"`
	Error any `json:"error"`
}

func containsPriority(m struct {
	ID        string `json:"id"`
	Role      string `json:"role"`
	Content   string `json:"content"`
	ToolCalls []struct {
		Name  string `json:"name"`
		Input any    `json:"input"`
	} `json:"toolCalls"`
}) bool {
	if strings.Contains(strings.ToLower(m.Content), "priority") {
		return true
	}
	for _, tc := range m.ToolCalls {
		b, _ := json.Marshal(tc.Input)
		if strings.Contains(strings.ToLower(tc.Name), "priority") || strings.Contains(strings.ToLower(string(b)), "priority") {
			return true
		}
	}
	return false
}

func main() {
	const path = "/api/v1/cache/entirehq/entire.io/session/5dbcd2da-0a2d-488a-a2e6-1d63a2b98e94/transcript"
	ctx := context.Background()
	token, err := auth.ResolveDataAPIToken(ctx, api.BaseURL())
	if err != nil {
		fmt.Fprintf(os.Stderr, "resolve token: %v\n", err)
		os.Exit(1)
	}
	client := api.NewClient(token)
	resp, err := client.Get(ctx, path)
	if err != nil {
		fmt.Fprintf(os.Stderr, "request: %v\n", err)
		os.Exit(1)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(resp.Body)
	if err != nil {
		fmt.Fprintf(os.Stderr, "read body: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("http_status=%d\n", resp.StatusCode)
	if resp.StatusCode != http.StatusOK {
		fmt.Printf("body=%s\n", strings.TrimSpace(string(body)))
		return
	}
	var r response
	if err := json.Unmarshal(body, &r); err != nil {
		fmt.Fprintf(os.Stderr, "decode: %v\n", err)
		os.Exit(1)
	}
	fmt.Printf("status=%q session_id=%q from_cache=%v sessions=%d checkpoints=%d\n", r.Status, r.SessionID, r.FromCache, len(r.Sessions), len(r.Checkpoints))
	fmt.Println("checkpoints:")
	for _, cp := range r.Checkpoints {
		fmt.Printf("- %s commit=%s ts=%s msg=%q\n", cp.CheckpointID, cp.CommitSha, cp.Timestamp, cp.Message)
