//                  - public GitHub repo (always public), OR
//                  - private repo with `public_sharing_enabled` AND a
//                    per-session share row in `session_shares`.
// Anything else collapses to a 404 Response.
async function resolveSessionAccess(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  db: Db,
  opts: { repoFullName: string; sessionId: string; userId: string | undefined },
): Promise<{ repo: Repo; mode: SessionAccessMode; isShared: boolean } | Response> {
  const { repoFullName, sessionId, userId } = opts

  if (userId) {
    const access = await db.repos.getByFullNameWithAccess(repoFullName, userId)
    if (access.status === "found") {
      // Authorized members always need `isShared` for the toggle UI state and
      // for the storage-repo gate bypass below — sharing is meaningful for
      // public repos with separate private storage too, not only private repos.
      const isShared = await db.sessionShares.isShared(access.repo.id, sessionId)
      return { repo: access.repo, mode: "authorized", isShared }
    }
  }

  const repo = await db.repos.getByFullName(repoFullName)
  if (!repo) return c.json({ error: "Not found" }, 404)

  if (!repo.is_private) {
    // Public source: anyone can hit the route, but a share row may still be
    // load-bearing when the storage repo is separate-private. Resolve it so
    // the transcript route can bypass the storage-repo gate for shared
    // sessions, and so the response carries the right `isShared` state.
    const isShared = await db.sessionShares.isShared(repo.id, sessionId)
    return { repo, mode: "public", isShared }
  }

  if (repo.public_sharing_enabled) {
    const isShared = await db.sessionShares.isShared(repo.id, sessionId)
    if (isShared) return { repo, mode: "public", isShared: true }
  }

  return c.json({ error: "Not found" }, 404)
}

interface SessionEnvelopeCheckpoint {
  checkpointId: string
  commitSha: string
  message: string
  additions: number
  deletions: number
  filesChanged: number
  timestamp: string
  authorUsername: string | null
}

interface SessionEnvelopeMeta {
  session: {
    agent: string
    displayName: string
    customName?: string | null
    prompt: string | null
    model: string | null
    steps: number
    checkpointCount: number
    createdAt: string | null
  }
  checkpoints: SessionEnvelopeCheckpoint[]
  tokenUsage: { inputTokens: number; outputTokens: number }
}

// What we persist in KV. Excludes per-request fields (repo metadata, viewer
// permissions) since those depend on the caller and must be re-derived on read.
interface SessionTranscriptCoreCacheEntry extends SessionEnvelopeMeta {
  sessions: SessionTranscript[]
}

function buildSessionResponseMeta(
  repo: Repo,
  mode: SessionAccessMode,
  isShared: boolean,
  shareToggleApplicable: boolean,
  viewerCanSeeCheckpointData: boolean,
  core: SessionEnvelopeMeta,
) {
  const [owner, name] = repo.full_name.split("/", 2)
  // A session is "public" when an unauthenticated viewer can read it. That's
  // (a) public source repo with no separate private storage to gate on, or
  // (b) any repo where this specific session has a share row (the share row is
  // the explicit grant; for private source repos the repo-level
  // public_sharing_enabled opt-in still applies on top).
  const isPublic = shareToggleApplicable
    ? isShared && (!repo.is_private || repo.public_sharing_enabled)
    : true
  return {
    repo: {
      owner,
      name,
      fullName: repo.full_name,
      defaultBranch: repo.default_branch,
      isPrivate: repo.is_private,
      publicSharingEnabled: repo.public_sharing_enabled,
      // True when sharing this session would actually grant access to anyone
      // who doesn't already have it. False on public source repos with no
      // separate private storage — the share toggle is meaningless there.
      shareToggleApplicable,
    },
    session: { ...core.session, customName: core.session.customName ?? null, isPublic },
    checkpoints: core.checkpoints,
    tokenUsage: core.tokenUsage,
    viewer: {
      canEdit: mode === "authorized",
      // Source-repo write access doesn't imply storage-repo access. The UI
      // uses this to hide the share toggle from members who can't grant a
      // share (they'd hit a 403 on POST anyway).
      canSeeCheckpointData: viewerCanSeeCheckpointData,
    },
  }
}

async function getMaterialisedSessionForTranscript(
  db: Db,
  repoId: string,
  sessionId: string,
): Promise<SessionListItem | null> {
  let repoSession = await db.sessions.getById(repoId, sessionId)
  if (!repoSession) {
    await db.sessions.materialise(repoId, [sessionId])
    repoSession = await db.sessions.getById(repoId, sessionId)
  }
  return repoSession
}

