export async function getBranchSyncState(
  db: Kysely<DB>,
  repoId: string,
  branch: string,
): Promise<RepoBranchSyncState | null> {
  const row = await db
    .selectFrom("repo_branch_sync_state")
    .selectAll()
    .where("repo_id", "=", repoId)
    .where("branch", "=", branch)
    .executeTakeFirst()

  return row ? mapBranchSyncStateRow(row) : null
}

export async function getBranchSyncStates(
  db: Kysely<DB>,
  repoId: string,
  branches: string[],
): Promise<Map<string, RepoBranchSyncState>> {
  if (branches.length === 0) return new Map()

  const rows = await db
    .selectFrom("repo_branch_sync_state")
    .selectAll()
    .where("repo_id", "=", repoId)
    .where("branch", "in", branches)
    .execute()

  return new Map(rows.map((row) => [row.branch, mapBranchSyncStateRow(row)]))
}

export async function getBranchSyncStateCount(db: Kysely<DB>, repoId: string): Promise<number> {
  const row = await db
    .selectFrom("repo_branch_sync_state")
    .select((eb) => eb.fn.count("id").as("count"))
    .where("repo_id", "=", repoId)
    .executeTakeFirst()

  return Number(row?.count ?? 0)
}

export async function getIncompleteBranchSyncStates(
  db: Kysely<DB>,
  staleThreshold: string,
  leaseExpiryThreshold: string,
  limit: number = 200,
): Promise<Array<{ repo_id: string; branch: string }>> {
  const rows = await db
    .selectFrom("repo_branch_sync_state")
    .select(["repo_id", "branch"])
    .where((eb) =>
      eb.not(
        eb.and([
          eb("status", "=", "syncing"),
          eb("locked_at", "is not", null),
          eb("locked_at", ">=", new Date(leaseExpiryThreshold)),
        ]),
      ),
    )
    .where((eb) =>
      eb.or([
        eb("history_complete", "=", 0),
        eb("status", "=", "error"),
        eb("last_synced_at", "is", null),
        eb("last_synced_at", "<", new Date(staleThreshold)),
      ]),
    )
    .limit(limit)
    .execute()

  return rows.map((row) => ({ repo_id: row.repo_id, branch: row.branch }))
}

export async function ensureBranchSyncState(
  db: Kysely<DB>,
  repoId: string,
  branch: string,
): Promise<RepoBranchSyncState> {
  // Fast path: row already exists (common case for refresh syncs)
  const existing = await db
    .selectFrom("repo_branch_sync_state")
    .selectAll()
    .where("repo_id", "=", repoId)
    .where("branch", "=", branch)
    .executeTakeFirst()

  if (existing) {
    return mapBranchSyncStateRow(existing)
  }

  // Row doesn't exist — create it
  await db
    .insertInto("repo_branch_sync_state")
    .values({
      id: generateId(),
      repo_id: repoId,
      branch,
      status: "pending" as RepoBranchSyncStatus,
      cursor_type: "page",
      next_page: 1,
      pages_fetched: 0,
      history_complete: 0,
      deleted_at: null,
    })
    .onDuplicateKeyUpdate({
      branch,
    })
    .execute()

  // Re-read after insert (MySQL doesn't return the row from INSERT...ON DUPLICATE)
  const row = await db
    .selectFrom("repo_branch_sync_state")
    .selectAll()
    .where("repo_id", "=", repoId)
    .where("branch", "=", branch)
    .executeTakeFirstOrThrow()

  return mapBranchSyncStateRow(row)
}

export async function tryAcquireBranchSyncLease(
  db: Kysely<DB>,
  repoId: string,
  branch: string,
  lockToken: string,
  leaseExpiryIso: string,
): Promise<boolean> {
  await ensureBranchSyncState(db, repoId, branch)

  const result = await db
    .updateTable("repo_branch_sync_state")
    .set({
      status: "syncing",
      locked_at: new Date(),
      lock_token: lockToken,
    })
    .where("repo_id", "=", repoId)
    .where("branch", "=", branch)
    .where((eb) =>
      eb.or([
        eb("locked_at", "is", null),
        eb("locked_at", "<", new Date(leaseExpiryIso)),
        eb("lock_token", "=", lockToken),
      ]),
    )
    .executeTakeFirst()

  return Number(result.numUpdatedRows) > 0
}

export async function updateBranchSyncProgress(
  db: Kysely<DB>,
  repoId: string,
  branch: string,
  updates: {
    status?: RepoBranchSyncStatus
    cursor_type?: string
    next_page?: number
    until_date?: string | null
    last_commit_sha?: string | null
    last_commit_date?: string | null
    pages_fetched?: number
    history_complete?: boolean
    last_synced_at?: string | null
    last_reconciled_at?: string | null
    last_known_head_sha?: string | null
    deleted_at?: string | null
    last_error?: string | null
    last_error_at?: string | null
    locked_at?: string | null
    lock_token?: string | null
  },
): Promise<void> {
  const patch: Record<string, unknown> = {}
  if (updates.status !== undefined) patch.status = updates.status
  if (updates.cursor_type !== undefined) patch.cursor_type = updates.cursor_type
  if (updates.next_page !== undefined) patch.next_page = updates.next_page
  if (updates.until_date !== undefined)
    patch.until_date = updates.until_date ? new Date(updates.until_date) : null
  if (updates.last_commit_sha !== undefined) patch.last_commit_sha = updates.last_commit_sha
  if (updates.last_commit_date !== undefined)
    patch.last_commit_date = updates.last_commit_date ? new Date(updates.last_commit_date) : null
  if (updates.pages_fetched !== undefined) patch.pages_fetched = updates.pages_fetched
  if (updates.history_complete !== undefined)
    patch.history_complete = updates.history_complete ? 1 : 0
  if (updates.last_synced_at !== undefined)
    patch.last_synced_at = updates.last_synced_at ? new Date(updates.last_synced_at) : null
  if (updates.last_reconciled_at !== undefined)
    patch.last_reconciled_at = updates.last_reconciled_at
      ? new Date(updates.last_reconciled_at)
      : null
  if (updates.last_known_head_sha !== undefined)
    patch.last_known_head_sha = updates.last_known_head_sha
  if (updates.deleted_at !== undefined)
    patch.deleted_at = updates.deleted_at ? new Date(updates.deleted_at) : null
  if (updates.last_error !== undefined) patch.last_error = updates.last_error
  if (updates.last_error_at !== undefined)
    patch.last_error_at = updates.last_error_at ? new Date(updates.last_error_at) : null
  if (updates.locked_at !== undefined)
    patch.locked_at = updates.locked_at ? new Date(updates.locked_at) : null
  if (updates.lock_token !== undefined) patch.lock_token = updates.lock_token

  if (Object.keys(patch).length === 0) return

  await db
    .updateTable("repo_branch_sync_state")
    .set(patch)
    .where("repo_id", "=", repoId)
    .where("branch", "=", branch)
    .execute()
}

