export async function getCheckpointsForSession(
  db: Kysely<DB>,
  repoId: string,
  sessionId: string,
): Promise<
  Array<{
    checkpoint_id: string
    sessions: string | null
    transcript_stripped: string | null
    payload_hydration_state: CheckpointPayloadHydrationState
    storage_version: number | null
    should_load_transcript: boolean
    commit_sha: string | null
    commit_message: string | null
    commit_author_username: string | null
    additions: number | null
    deletions: number | null
    files_changed: number | null
    commit_date: string | null
  }>
> {
  const orderedCheckpoints = await db
    .selectFrom("repo_checkpoints as cp")
    .innerJoin("repo_checkpoint_commits as cc", (join) =>
      join
        .onRef("cc.repo_id", "=", "cp.repo_id")
        .onRef("cc.checkpoint_id", "=", "cp.checkpoint_id"),
    )
    .innerJoin("repo_commits as rc", (join) =>
      join.onRef("rc.repo_id", "=", "cc.repo_id").onRef("rc.commit_sha", "=", "cc.commit_sha"),
    )
    .select(["cp.checkpoint_id", sql<string>`MIN(rc.commit_date)`.as("commit_date")])
    .where("cp.repo_id", "=", repoId)
    .where(sql<boolean>`cp.session_ids LIKE ${`%${escapeLike(sessionId)}%`}`)
    .groupBy("cp.checkpoint_id")
    .orderBy("commit_date", "asc")
    .execute()

  if (orderedCheckpoints.length === 0) return []

  const checkpointIds = orderedCheckpoints.map((row) => row.checkpoint_id)

  // Metadata-only payload SELECT — deliberately no transcript_stripped here.
  // The blob is fetched separately via getCheckpointTranscriptBatch so each
  // gRPC response stays well under the 64 MiB cap regardless of how fat any
  // individual transcript is. `cp.created_at` is the session-derived
  // chronology key, used below to identify the latest snapshot. We can't
  // use the ordering query's MIN(commit_date) for that because commit
  // chronology can diverge from session chronology under rebases /
  // cherry-picks — a later session checkpoint can point at an older commit.
  const payloadRows = await db
    .selectFrom("repo_checkpoints as cp")
    .select([
      "cp.checkpoint_id",
      "cp.sessions",
      "cp.payload_hydration_state",
      "cp.storage_version",
      "cp.dead_session_indices",
      "cp.created_at",
    ])
    .where("cp.repo_id", "=", repoId)
    .where("cp.checkpoint_id", "in", checkpointIds)
    .execute()

  // `everyRowPresent` defends against `.every()` returning true vacuously
  // when a checkpoint is missing from payloadRows entirely.
  const everyRowPresent = payloadRows.length === checkpointIds.length
  const allHydrated =
    everyRowPresent &&
    payloadRows.every(
      (row) =>
        row.payload_hydration_state === "complete" ||
        row.payload_hydration_state === "complete_empty",
    )
  // Per-session, because the slicing decision is per-session: for a
  // multi-session checkpoint the queried sessionId and the latest sessionId
  // can disagree (one offset-only, the other UUID-cumulative).
