    transcriptIdsToFetch.length > 0
      ? await getCheckpointTranscriptBatch(db, repoId, transcriptIdsToFetch)
      : []
  const transcriptById = new Map(
    transcriptRows.map((row) => [row.checkpoint_id, row.transcript_stripped] as const),
  )
  const shouldLoadTranscriptIds = new Set(transcriptIdsToFetch)

  const payloadById = new Map<
    string,
    {
      sessions: unknown
      transcript_stripped: unknown
      payload_hydration_state: CheckpointPayloadHydrationState
      storage_version: number | null
      dead_session_indices: number[] | null
    }
  >()
  for (const row of payloadRows) {
    payloadById.set(row.checkpoint_id, {
      sessions: row.sessions,
      transcript_stripped: transcriptById.get(row.checkpoint_id) ?? null,
      payload_hydration_state: parsePayloadHydrationState(row.payload_hydration_state),
      storage_version: row.storage_version ?? null,
      dead_session_indices: parseDeadSessionIndices(row.dead_session_indices),
