  // commit per checkpoint — that row is the representative we expose. No JSON
  // columns in this query, so the sort buffer stays small even with many rows.
  const commitRows = await db
    .selectFrom("repo_checkpoint_commits as cc")
    .innerJoin("repo_commits as rc", (join) =>
      join.onRef("rc.repo_id", "=", "cc.repo_id").onRef("rc.commit_sha", "=", "cc.commit_sha"),
    )
    .select([
      "cc.checkpoint_id",
      "rc.commit_sha",
      "rc.commit_message",
      "rc.commit_author_username",
      "rc.additions",
      "rc.deletions",
      "rc.files_changed",
      "rc.commit_date",
