package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"os"
	"strings"

	"github.com/entireio/cli/cmd/entire/cli/api"
	"github.com/entireio/cli/cmd/entire/cli/auth"
)

type endpoint struct {
	Label string
	Path  string
}

type response struct {
	Status       string `json:"status"`
	SessionID    string `json:"sessionId"`
	FromCache    bool   `json:"from_cache"`
	NextCursor   string `json:"next_cursor"`
	RepoFullName string `json:"repo_full_name"`
	Sessions     []struct {
		SessionID string `json:"sessionId"`
		Agent     string `json:"agent"`
		Messages  []struct {
			ID        string `json:"id"`
			Role      string `json:"role"`
			Content   string `json:"content"`
			ToolCalls []struct {
				Name  string `json:"name"`
				Input any    `json:"input"`
			} `json:"toolCalls"`
		} `json:"messages"`
	} `json:"sessions"`
	Checkpoints []struct {
		CheckpointID string `json:"checkpointId"`
		CommitSha    string `json:"commitSha"`
		Message      string `json:"message"`
		Timestamp    string `json:"timestamp"`
	} `json:"checkpoints"`
	Repos []struct {
		FullName string `json:"full_name"`
		Private  bool   `json:"private"`
	} `json:"repos"`
	Error any `json:"error"`
}

func main() {
	endpoints := []endpoint{
		{
			Label: "current user's cached repos",
			Path:  "/api/v1/cache/repos",
		},
		{
			Label: "sessions branch demo/priority-label-colors",
			Path:  "/api/v1/cache/entirehq/entire.io/sessions?branch=demo%2Fpriority-label-colors&limit=200",
		},
		{
			Label: "sessions branch merge-in-trails",
			Path:  "/api/v1/cache/entirehq/entire.io/sessions?branch=merge-in-trails&limit=200",
		},
		{
			Label: "checkpoint 585967f44df5 transcript",
			Path:  "/api/v1/cache/entirehq/entire.io/checkpoints/585967f44df5/transcript",
		},
		{
			Label: "checkpoint bec4c4c2ea8b transcript",
			Path:  "/api/v1/cache/entirehq/entire.io/checkpoints/bec4c4c2ea8b/transcript",
		},
		{
			Label: "session 5dbcd2da transcript",
			Path:  "/api/v1/cache/entirehq/entire.io/session/5dbcd2da-0a2d-488a-a2e6-1d63a2b98e94/transcript",
		},
	}

	ctx := context.Background()
	token, err := auth.ResolveDataAPIToken(ctx, api.BaseURL())
	if err != nil {
		fmt.Fprintf(os.Stderr, "resolve token: %v\n", err)
		os.Exit(1)
	}

	client := api.NewClient(token)
	for _, endpoint := range endpoints {
		fmt.Printf("\n== %s ==\n%s\n", endpoint.Label, endpoint.Path)
		resp, err := client.Get(ctx, endpoint.Path)
		if err != nil {
			fmt.Printf("request_error=%v\n", err)
			continue
		}

		body, err := io.ReadAll(resp.Body)
		resp.Body.Close()
		if err != nil {
			fmt.Printf("read_error=%v\n", err)
			continue
		}

		fmt.Printf("http_status=%d\n", resp.StatusCode)
		if resp.StatusCode != http.StatusOK {
			fmt.Printf("body=%s\n", truncate(strings.TrimSpace(string(body)), 1000))
			continue
		}
		printSummary(body)
	}
}

func printSummary(body []byte) {
	var r response
	if err := json.Unmarshal(body, &r); err != nil {
		fmt.Printf("decode_error=%v body=%s\n", err, truncate(strings.TrimSpace(string(body)), 1000))
		return
	}

	fmt.Printf(
		"status=%q repo=%q session_id=%q from_cache=%v sessions=%d checkpoints=%d next_cursor=%q\n",
		r.Status,
		r.RepoFullName,
		r.SessionID,
		r.FromCache,
		len(r.Sessions),
		len(r.Checkpoints),
		r.NextCursor,
	)
	if len(r.Repos) > 0 {
		found := false
		fmt.Printf("repos=%d\n", len(r.Repos))
		for _, repo := range r.Repos {
			if strings.EqualFold(repo.FullName, "entirehq/entire.io") {
				found = true
				fmt.Printf("  target_repo full_name=%s private=%v\n", repo.FullName, repo.Private)
			}
		}
		fmt.Printf("target_repo_present=%v\n", found)
	}
	if len(r.Checkpoints) > 0 {
		fmt.Println("checkpoints:")
	}
	for _, cp := range r.Checkpoints {
		fmt.Printf("- %s commit=%s ts=%s msg=%q\n", cp.CheckpointID, cp.CommitSha, cp.Timestamp, cp.Message)
	}

	for i, s := range r.Sessions {
		priorityHits := 0
		for _, m := range s.Messages {
			if containsPriority(m) {
				priorityHits++
			}
		}
		fmt.Printf("session[%d] id=%s agent=%s messages=%d priority_hits=%d\n", i, s.SessionID, s.Agent, len(s.Messages), priorityHits)
		for _, m := range s.Messages {
			if !containsPriority(m) {
				continue
			}
			content := strings.Join(strings.Fields(m.Content), " ")
			fmt.Printf("  hit role=%s id=%s content=%q tools=%d\n", m.Role, m.ID, truncate(content, 180), len(m.ToolCalls))
		}
	}
}

func containsPriority(m struct {
	ID        string `json:"id"`
	Role      string `json:"role"`
	Content   string `json:"content"`
	ToolCalls []struct {
		Name  string `json:"name"`
		Input any    `json:"input"`
	} `json:"toolCalls"`
}) bool {
	if strings.Contains(strings.ToLower(m.Content), "priority") {
		return true
	}
	for _, tc := range m.ToolCalls {
		b, _ := json.Marshal(tc.Input)
		if strings.Contains(strings.ToLower(tc.Name), "priority") || strings.Contains(strings.ToLower(string(b)), "priority") {
			return true
		}
	}
	return false
}

func truncate(value string, limit int) string {
	if len(value) <= limit {
		return value
	}
	return value[:limit] + "..."
}

