const CHECKPOINT_LINK_AUDIT_DEFAULT_LIMIT = 1000
const CHECKPOINT_LINK_AUDIT_MAX_LIMIT = 1000

function parsePositiveInteger(value: unknown): number | null {
  const parsed = typeof value === "number" ? value : typeof value === "string" ? Number(value) : NaN
  return Number.isInteger(parsed) && parsed > 0 ? parsed : null
}

/**
 * POST /admin/v2/git-source/audit-checkpoint-links
 *
 * Read-only incident tool for comparing cached branch commits against
 * Entire-Checkpoint trailers and repo_checkpoint_commits rows.
 *
 * Body shape:
 *   {
 *     repo_id?: string,
 *     repo_full_name?: string,
 *     repoFullName?: string,
 *     branch?: string,
 *     trail_number?: number,
 *     limit?: number,
 *     include_linked?: boolean,
 *     include_no_trailer?: boolean
 *   }
 */
adminRoutes.post("/v2/git-source/audit-checkpoint-links", async (c) => {
  const body = await c.req
    .json<{
      repo_id?: string
      repo_full_name?: string
      repoFullName?: string
      branch?: string
      trail_number?: number | string
      limit?: number | string
      include_linked?: boolean
      include_no_trailer?: boolean
    }>()
    .catch(
      () =>
        ({}) as {
          repo_id?: string
          repo_full_name?: string
          repoFullName?: string
          branch?: string
          trail_number?: number | string
          limit?: number | string
          include_linked?: boolean
          include_no_trailer?: boolean
        },
    )

  const repoFullName = body.repo_full_name ?? body.repoFullName
  if (!body.repo_id && !repoFullName) {
    return c.json({ error: "repo_id or repo_full_name is required" }, 400)
  }

  const rawLimit = body.limit === undefined ? CHECKPOINT_LINK_AUDIT_DEFAULT_LIMIT : body.limit
  const parsedLimit = parsePositiveInteger(rawLimit)
  if (parsedLimit === null) {
    return c.json({ error: "limit must be a positive integer" }, 400)
  }
  const limit = Math.min(parsedLimit, CHECKPOINT_LINK_AUDIT_MAX_LIMIT)

  const db = getDb(c.env)
  const repo = body.repo_id
    ? await db.repos.getById(body.repo_id)
    : await db.repos.getByFullName(repoFullName!)
  if (!repo) {
    return c.json({ error: "repo not found" }, 404)
  }

  let branch = body.branch?.trim() || null
  let trailNumber: number | null = null
  if (body.trail_number !== undefined) {
    const parsedTrailNumber = parsePositiveInteger(body.trail_number)
    if (parsedTrailNumber === null) {
      return c.json({ error: "trail_number must be a positive integer" }, 400)
    }
    trailNumber = parsedTrailNumber
  }

  if (!branch && trailNumber !== null) {
    const trail = await db.trails.getByNumber(repo.id, trailNumber)
    if (!trail) {
      return c.json({ error: "trail not found" }, 404)
    }
    branch = trail.branch ?? trail.original_branch
  }

  if (!branch) {
    return c.json({ error: "branch or trail_number is required" }, 400)
  }

  const commits = await db.checkpoints.getCommitsForBranch(repo.id, branch, { limit })
  const trailerLinks = commits.flatMap((commit) =>
    extractCheckpointIds(commit.commit_message ?? "").map((checkpointId) => ({
      checkpoint_id: checkpointId,
      commit_sha: commit.commit_sha,
    })),
  )
  const existingLinks =
    trailerLinks.length > 0
      ? await db.checkpoints.listExistingCheckpointCommitLinks(repo.id, trailerLinks)
      : []
  const audit = buildCheckpointLinkAudit({
    commits,
    existingLinks,
    includeLinked: body.include_linked === true,
    includeNoTrailer: body.include_no_trailer === true,
  })

  return c.json({
    success: true,
    repo_id: repo.id,
    repo_full_name: repo.full_name,
    branch,
    trail_number: trailNumber,
    limit,
    ...audit,
  })
})

/**
 * POST /admin/v2/git-source/enrich-authors
 *
 * One-shot backfill — enqueues an enrich_commit_authors task per repo
 * that has at least one unresolved-and-uncached commit author. The task
 * self-perpetuates (see runAuthorEnrichment) until each repo's
 * unresolved pool is drained.
 *
 * Body shape: { repo_id?: string, repo_full_name?: string, max_repos?: number }
 *   - With repo_id / repo_full_name: enqueue exactly that repo (no pre-filter).
 *   - Without either: scan repo_commits for repos with work to do.
 *   - max_repos caps the scan-and-enqueue batch (default 1000) so a single
 *     admin call doesn't fill the queue.
 */
adminRoutes.post("/v2/git-source/enrich-authors", async (c) => {
  const body = await c.req
    .json<{ repo_id?: string; repo_full_name?: string; max_repos?: number }>()
    .catch(() => ({}) as { repo_id?: string; repo_full_name?: string; max_repos?: number })

  const userId = c.get("userId") as string | undefined
  console.log(
    `[admin/git-source/enrich-authors] caller=${userId ?? "unknown"} repo_id=${body.repo_id ?? "(all)"} repo_full_name=${body.repo_full_name ?? "(by_id_or_all)"} max_repos=${body.max_repos ?? "default"}`,
  )

  const db = getDb(c.env)
  if (!c.env.REPO_SYNC_QUEUE) {
    return c.json({ error: "REPO_SYNC_QUEUE binding is not configured" }, 500)
  }

  if (body.repo_id || body.repo_full_name) {
    const repo = body.repo_id
      ? await db.repos.getById(body.repo_id)
      : await db.repos.getByFullName(body.repo_full_name!)
    if (!repo) return c.json({ error: "repo not found" }, 404)
    const result = await enqueueAuthorEnrichment(c.env, repo.id, repo.full_name)
    return c.json({ success: result.ok, repo_id: repo.id, ...result })
  }

  // Scan: find distinct repo_ids with at least one unresolved author that
  // isn't already in the negative cache. Mirrors the filter
  // findUnresolvedCommitAuthors uses so we don't enqueue tasks that would
  // immediately return zero work.
  //
  // Require an installation reachable from the repo — either via the
  // direct FK or via owner-name fallback (which the queue worker also
  // honors). Without this, the LIMIT budget can be consumed by repos
  // whose installation is gone, starving backfillable ones.
  const maxRepos = Math.min(Math.max(body.max_repos ?? 1000, 1), 10000)
  const repoRows = await getKysely(c.env)
    .selectFrom("repo_commits")
    .innerJoin("repos", "repos.id", "repo_commits.repo_id")
    .select(["repo_commits.repo_id as id", "repos.full_name"])
    .distinct()
    .where("repo_commits.commit_author_email", "is not", null)
    .where("repo_commits.commit_author_username", "is", null)
    .where(({ not, exists, selectFrom }) =>
      not(
        exists(
          // Mirror findUnresolvedCommitAuthors: only FRESH negative cache
          // entries should hide a repo from the scan. Aged-out negatives
          // need a chance to be re-resolved on the next pass.
          selectFrom("github_email_mappings as gem")
            .select("gem.email")
            .whereRef("gem.email", "=", "repo_commits.commit_author_email")
            .where("gem.github_id", "is", null)
            .where(
              sql<boolean>`gem.resolved_at > NOW() - INTERVAL ${sql.lit(NEGATIVE_CACHE_TTL_DAYS)} DAY`,
            ),
        ),
      ),
    )
    // Filter to repos that have an unsuspended installation reachable
    // by either FK or owner-name. This matches the realistic worker
    // path: a deleted installation row triggers owner fallback (so we
    // still want those), a suspended-only chain produces a guaranteed
    // failure (so we exclude those).
    //
    // Edge case: a repo whose FK points to a suspended installation
    // while the owner has a separate active one will be admitted here
    // but the worker (which uses FK first and doesn't try owner if it
    // resolves) will still fail token acquisition. We accept this — it
    // requires a rare reinstall-into-new-installation state, and the
    // failure is bounded to one queue task per such repo.
    .where((eb) =>
      eb.exists(
        eb
          .selectFrom("installations as inst")
          .select("inst.id")
          .where("inst.suspended_at", "is", null)
          .where((iEb) =>
            iEb.or([
              iEb("inst.id", "=", iEb.ref("repos.installation_id")),
              iEb(
                "inst.account_login",
                "=",
                sql<string>`SUBSTRING_INDEX(${sql.ref("repos.full_name")}, '/', 1)`,
              ),
            ]),
          ),
      ),
    )
    .limit(maxRepos)
    .execute()

  const results = await mapWithConcurrency(repoRows, (row) =>
    enqueueAuthorEnrichment(c.env, row.id, row.full_name),
  )
  const enqueued = results.filter((r) => r.ok).length
  const failed = results.length - enqueued
  // Report failure if there was work to do and nothing got enqueued —
  // operators rely on the success flag during incidents.
  const success = repoRows.length === 0 || enqueued > 0
  return c.json({
    success,
    reposScanned: repoRows.length,
    enqueued,
    failed,
    cappedAt: maxRepos,
  })
})

/**
 * POST /admin/v2/git-source/backfill-branch-commit-dates
 *
 * Backfills repo_branch_commits.commit_date (denormalized from repo_commits)
 * for one repo, in a bounded batch. Resumable: call repeatedly until the
 * response reports `done: true` (a batch that updates 0 rows). Scoped to a
 * single repo per call and capped by `limit` so it never becomes the kind of
 * unbounded write on this table that caused the checkpoint-sync incident.
 *
 * The denormalized column powers the commit-list query's
 * FLAG_COMMIT_LIST_BRANCH_DATE path — keep that flag OFF for a repo until this
 * reports done for it. New/edited rows are filled by the upsert write path;
 * this fills the historical rows.
 *
 * Body: { repo_id?: string, repo_full_name?: string, limit?: number }
 */
adminRoutes.post("/v2/git-source/backfill-branch-commit-dates", async (c) => {
  const body = await c.req
    .json<{ repo_id?: string; repo_full_name?: string; limit?: number }>()
    .catch(() => ({}) as { repo_id?: string; repo_full_name?: string; limit?: number })

  if (!body.repo_id && !body.repo_full_name) {
    return c.json({ error: "repo_id or repo_full_name is required" }, 400)
  }

  const db = getDb(c.env)
  const repo = body.repo_id
    ? await db.repos.getById(body.repo_id)
    : await db.repos.getByFullName(body.repo_full_name!)
  if (!repo) return c.json({ error: "repo not found" }, 404)

  const limit = Math.min(Math.max(body.limit ?? 1000, 1), 5000)
  const userId = c.get("userId") as string | undefined
  console.log(
    `[admin/git-source/backfill-branch-commit-dates] caller=${userId ?? "unknown"} repo=${repo.full_name} limit=${limit}`,
  )

  // Single-table UPDATE with a correlated subquery + LIMIT: bounded, stays
  // within one keyspace, and only touches rows still missing the date.
  //
  // The EXISTS guard is load-bearing for `done`: numAffectedRows counts
  // *changed* rows, not matched ones. A repo_branch_commits row whose
  // commit_sha has no repo_commits match (or whose match has a NULL date)
  // would be matched by `commit_date IS NULL` but set NULL→NULL (no change),
  // so it wouldn't count toward `updated` — making `updated < limit` report
  // done prematurely while fillable rows remain (LIMIT has no ORDER BY), and
  // re-scanning those orphans on every call. Restricting to fillable rows
  // makes every matched row a change, so `updated < limit` is exact and
  // orphans are skipped.
  const result = await sql<{ affectedRows?: number }>`
    UPDATE repo_branch_commits
    SET commit_date = (
      SELECT rc.commit_date FROM repo_commits rc
      WHERE rc.repo_id = repo_branch_commits.repo_id
        AND rc.commit_sha = repo_branch_commits.commit_sha
    )
    WHERE repo_branch_commits.repo_id = ${repo.id}
      AND repo_branch_commits.commit_date IS NULL
      AND EXISTS (
        SELECT 1 FROM repo_commits rc
        WHERE rc.repo_id = repo_branch_commits.repo_id
          AND rc.commit_sha = repo_branch_commits.commit_sha
          AND rc.commit_date IS NOT NULL
      )
    LIMIT ${limit}
  `.execute(getKysely(c.env))

  const updated = Number(result.numAffectedRows ?? 0)
  // A batch shorter than the cap means no more *fillable* rows remain.
  const done = updated < limit

  // On the final batch, surface how many NULL rows are left un-fillable (no
  // matching repo_commits date yet) so the flag isn't flipped on while genuine
  // gaps exist — those rows would silently drop from the list under the
  // bc.commit_date ordering. Best-effort: never fail the backfill on it.
  let unfillableRemaining: number | null = null
  if (done) {
    try {
      const gap = await sql<{ n: number }>`
        SELECT COUNT(*) AS n FROM repo_branch_commits bc
        WHERE bc.repo_id = ${repo.id}
          AND bc.commit_date IS NULL
      `.execute(getKysely(c.env))
      unfillableRemaining = Number(gap.rows[0]?.n ?? 0)
      if (unfillableRemaining > 0) {
        console.warn(
          `[admin/git-source/backfill-branch-commit-dates] repo=${repo.full_name} fillable backfill done but ${unfillableRemaining} NULL rows are un-fillable (no repo_commits date) — do NOT enable the flag for this repo yet`,
        )
      }
    } catch (err) {
      console.warn(
        `[admin/git-source/backfill-branch-commit-dates] remaining-gap count failed for ${repo.full_name}:`,
        err instanceof Error ? err.message : String(err),
      )
    }
  }

  return c.json({
    success: true,
    repo_id: repo.id,
    repo_full_name: repo.full_name,
    updated,
    limit,
    done,
    unfillableRemaining,
  })
})

