  if (repo.installation_id) {
    installation = await db.installations.get(repo.installation_id)
  }
  if (!installation || installation.suspended_at) {
    const ownerInstallation = await db.installations.getByOwner(owner)
    if (ownerInstallation && (!installation || !ownerInstallation.suspended_at)) {
      installation = ownerInstallation
    }
