// Admin: Repair checkpoint session metadata
// Re-reads session data from entire/checkpoints/v1 tree for checkpoints
// that are missing session metadata (sessions IS NULL). Fixes the race
// condition where processCommitPushEvent created the checkpoint before
// processSessionsPushEvent could fill in the metadata.
adminRoutes.post("/repair-checkpoint-metadata", async (c) => {
  const body = await c.req
    .json<{
      repoFullName?: string
      repoIds?: string[]
      dryRun?: boolean
    }>()
    .catch(() => ({
      repoFullName: undefined,
      repoIds: undefined,
      dryRun: undefined,
    }))

  const db = getDb(c.env)
  const dryRun = body.dryRun ?? false

  // Determine which repos to process (keep full records to avoid re-fetching)
  let repos: Repo[]
  if (body.repoFullName) {
    const repo = await db.repos.getByFullName(body.repoFullName)
    repos = repo ? [repo] : []
  } else if (body.repoIds?.length) {
    const results = await Promise.all(body.repoIds.map((id) => db.repos.getById(id)))
    repos = results.filter((r): r is NonNullable<typeof r> => r !== null)
  } else {
    return c.json({ error: "Must specify repoFullName or repoIds" }, 400)
  }

  if (repos.length === 0) {
    return c.json({ success: false, message: "No matching repos found" })
  }

  const stats = {
    reposProcessed: 0,
    reposSkipped: 0,
    checkpointsFound: 0,
    checkpointsRepaired: 0,
  }
  const errors: string[] = []

  for (const repo of repos) {
    try {
      // Get installation token for this repo
      let githubInstallationId: number | null = null
      if (repo.installation_id) {
        githubInstallationId = await db.installations.getGithubId(repo.installation_id)
      }
      if (!githubInstallationId) {
        const owner = repo.full_name.split("/")[0]
        githubInstallationId = await db.installations.getGithubIdByOwner(owner)
      }
      if (!githubInstallationId) {
        errors.push(`${repo.full_name}: no installation found`)
        stats.reposSkipped++
        continue
      }

      let token: string
      try {
        token = await getInstallationToken(
          githubInstallationId,
          {
            appId: c.env.GITHUB_CLIENT_ID,
            privateKey: c.env.GITHUB_APP_PRIVATE_KEY,
          },
          c.env.ENTIRE_CACHE,
        )
      } catch (err) {
        errors.push(
          `${repo.full_name}: token error: ${err instanceof Error ? err.message : String(err)}`,
        )
