 * metadata.json the transcript-derived value never overrides it. This is the
 * single home for the "metadata wins" precedence — both hydration paths
 * (streaming and bulk-fetch) funnel through it. Mutates in place; callers pass
 * the SessionInfo that will be persisted on the checkpoint row.
 */
export function applyModelBackfill(
  session: SessionInfo | undefined,
  model: string | null | undefined,
): void {
  const candidate = model?.trim()
  if (session && candidate && !session.model?.trim()) session.model = candidate
