function collectSessionIdsForHydration(
  checkpointDataArray: CheckpointWebhookData[],
  touched: Set<string>,
): string[] {
  if (touched.size === 0) return []
  const sessionIds = new Set<string>()
  for (const cp of checkpointDataArray) {
    if (!touched.has(cp.checkpoint_id)) continue
    const sessions = cp.sessions as SessionInfo[] | null | undefined
    if (!sessions) continue
    for (const entry of sessions) {
      if (entry?.sessionId) sessionIds.add(entry.sessionId)
    }
  }
  return [...sessionIds]
}

