// Resolve the transcript file path for session 0 by reading metadata.json
// (which may specify a custom transcript location). Falls back to the
// default path when metadata.json is missing or has no custom path.
async function resolveSession0TranscriptPath(
  repoProvider: RepoReadProvider,
  repoFullName: string,
  checkpointId: string,
  loc: { ref: string; transcriptFilename: string },
  token: string,
  onError?: (err: unknown, meta: Record<string, unknown>) => void,
): Promise<string> {
  const folder = checkpointFolderPath(checkpointId)
  const defaultPath = `${folder}/0/${loc.transcriptFilename}`
  // Fetch errors (transient network/GitHub) propagate so the streaming path
  // surfaces them via its onError — falling back silently to the default
  // path would hide a real outage and corrupt subsequent reads if the
  // custom path is required. Only JSON.parse failures (corrupt metadata)
  // fall back to the default path.
  const metadataContent = await repoProvider.getFileAtCommit(
    repoFullName,
    `${folder}/metadata.json`,
    loc.ref,
    token,
  )
  if (!metadataContent) return defaultPath
  let meta: { sessions?: Array<{ transcript?: string }> }
  try {
    meta = JSON.parse(metadataContent) as { sessions?: Array<{ transcript?: string }> }
  } catch (err) {
    onError?.(err, { stage: "resolve_session0_transcript_path", checkpointId, kind: "json_parse" })
    return defaultPath
  }
  const customPath = meta.sessions?.[0]?.transcript
  if (typeof customPath === "string" && customPath) {
    return stripLeadingSlash(customPath)
  }
  return defaultPath
}

