// Classify a fetch+strip result into a terminal hydration state. Centralised so
// the fetch path and per-chunk commit helper have a single contract to consume.
type ChunkOutcome = {
  checkpoint: CheckpointWebhookData
  classification: "complete" | "complete_empty" | "error"
  sessions: Record<string, StoredTranscriptSession> | null
  deadSessionIndices?: number[]
  failureReasons: CheckpointFailureReason[]
}

export interface CheckpointFailureReason {
  /** Session id this failure is bound to. `null` for failures that don't bind
   * to a single session (e.g. metadata.json fetch, wholesale batch failure). */
  sessionId: string | null
  /** Position in the checkpoint's transcriptPaths array; `null` for
   * non-per-session failures. */
  sessionIndex: number | null
  /** Upstream call's path. `"<batch>"` for wholesale batch failures, the
   * literal metadata.json path for root metadata failures. */
  path: string
  /** Stringified upstream error message. */
  error: string
}

function buildFailureReasons(
  transientErrors: TranscriptFetchError[],
  checkpoint: CheckpointWebhookData,
): CheckpointFailureReason[] {
  if (transientErrors.length === 0) return []
  const sessionMetadata = (checkpoint.sessions as SessionInfo[] | null) ?? null
  return transientErrors.map((e) => ({
    sessionId:
      e.sessionIndex !== null ? (sessionMetadata?.[e.sessionIndex]?.sessionId ?? null) : null,
    sessionIndex: e.sessionIndex,
    path: e.path,
    error: e.error,
  }))
}

interface FetchOutcome {
  sessions: Record<string, StoredTranscriptSession> | null
  transientErrors: TranscriptFetchError[]
}

function classifyHydrationResult(
  checkpoint: CheckpointWebhookData,
  fetch: FetchOutcome,
): ChunkOutcome {
  if (!fetch.sessions) {
    return {
      checkpoint,
      classification: "error",
      sessions: null,
      failureReasons: buildFailureReasons(fetch.transientErrors, checkpoint),
    }
  }

  const isClean = fetch.transientErrors.length === 0 && checkpoint.sessions !== null
  const hasContent = Object.keys(fetch.sessions).length > 0

  if (hasContent) {
    if (!isClean) {
      // Partial fetch: a transient error tripped some sessions but others
      // came back successfully. Preserve the partial content so the chunk
      // commit can still write it to R2 — keeps parity with the previous
      // behavior of "write whatever we managed to fetch even on error".
      // State stays 'error' so the tail batch surfaces failure and a later
      // hydration attempt can retry the missing sessions.
      return {
        checkpoint,
        classification: "error",
        sessions: fetch.sessions,
        failureReasons: buildFailureReasons(fetch.transientErrors, checkpoint),
      }
    }
    const sessionCount = checkpoint.session_count ?? 1
    return {
      checkpoint,
      classification: "complete",
      sessions: fetch.sessions,
      deadSessionIndices: computeDeadSessionIndices(sessionCount, fetch.sessions),
      failureReasons: [],
    }
  }
  if (!isClean) {
    return {
      checkpoint,
      classification: "error",
      sessions: null,
      failureReasons: buildFailureReasons(fetch.transientErrors, checkpoint),
    }
  }

  const sessionCount = checkpoint.session_count ?? 1
  const deadIndices = computeDeadSessionIndices(sessionCount, fetch.sessions)
  if (deadIndices.length === 0) {
    return {
      checkpoint,
      classification: "error",
      sessions: null,
      failureReasons: buildFailureReasons(fetch.transientErrors, checkpoint),
    }
  }
  return {
    checkpoint,
    classification: "complete_empty",
    sessions: null,
    deadSessionIndices: deadIndices,
    failureReasons: [],
  }
}

