export async function deleteCheckpointCommitsByBranch(
  db: Kysely<DB>,
  repoId: string,
  _branch: string,
): Promise<number> {
  // Use the Kysely builder to emit `DELETE FROM repo_checkpoint_commits AS rcc
  // WHERE … NOT EXISTS (…)` rather than the multi-table-DELETE form (`DELETE
  // rcc FROM repo_checkpoint_commits rcc …`). Vitess silently mis-plans the
  // multi-table form here — the DELETE no-ops on prod even when rows match —
  // while the single-table-with-alias form below is the same shape
  // `deleteOrphanedCheckpoints` uses successfully in production.
  const result = await db
    .deleteFrom("repo_checkpoint_commits as rcc")
    .where("rcc.repo_id", "=", repoId)
    .where(({ not, exists, selectFrom }) =>
      not(
        exists(
          selectFrom("repo_branch_commits as rbc")
            .select(sql`1`.as("one"))
            .whereRef("rbc.repo_id", "=", "rcc.repo_id")
            .whereRef("rbc.commit_sha", "=", "rcc.commit_sha"),
        ),
      ),
    )
    .executeTakeFirst()

  return Number(result.numDeletedRows ?? 0)
}

