export async function deleteRecentRepoBranchCommitsNotInSet(
  db: Kysely<DB>,
  repoId: string,
  branch: string,
  oldestCommitDate: string,
  validCommitShas: string[],
): Promise<number> {
  if (validCommitShas.length === 0) {
    return 0
  }

  const result = await db
    .deleteFrom("repo_branch_commits")
    .where("repo_id", "=", repoId)
    .where("branch", "=", branch)
    .where("commit_sha", "not in", validCommitShas)
    .where("commit_sha", "in", (eb) =>
      eb
        .selectFrom("repo_commits")
        .select("commit_sha")
        .where("repo_id", "=", repoId)
        .where("commit_date", ">=", new Date(oldestCommitDate)),
    )
    .executeTakeFirst()

  const deleted = Number(result.numDeletedRows)
  if (deleted > 0) {
    await refreshTrailCodeChangesForBranchImpact(db, repoId, branch)
  }
  return deleted
