type LegacyRepoSyncTask =
  | "sync_recent"
  | "sync_branch_history"
  | "checkpoint_sync"
  | "fastlane_sync"
  | "branch_commit_backfill"

export type RepoSyncMessage = Omit<GitSourceRepoSyncMessage, "task"> & {
  // Current producers always set one of GitSourceRepoSyncMessage["task"].
  // Legacy values/taskless messages are accepted temporarily so in-flight
  // queue backlog from pre-deploy producers is translated instead of acked
  // as unknown.
  task?: GitSourceRepoSyncMessage["task"] | LegacyRepoSyncTask
  branches?: string[]
}

// TTL for sync:lastUpdate KV entries (7 days)
const SYNC_LAST_UPDATE_TTL = 60 * 60 * 24 * 7

const REPO_SYNC_TASKS = [
  "reconcile_branch",
  "enrich_commit_stats",
  "enrich_commit_authors",
  "process_checkpoints",
] as const
const LEGACY_REPO_SYNC_TASKS = [
  "sync_recent",
  "sync_branch_history",
  "checkpoint_sync",
  "fastlane_sync",
  "branch_commit_backfill",
] as const
const ACCEPTED_REPO_SYNC_TASKS = [...REPO_SYNC_TASKS, ...LEGACY_REPO_SYNC_TASKS] as const

type NormalizedRepoSyncTask =
  | GitSourceRepoSyncMessage["task"]
  | "legacy_sync_recent"
  | "legacy_sync_branch_history"

function normalizeRepoSyncTask(task: RepoSyncMessage["task"]): NormalizedRepoSyncTask {
  if (!task || task === "checkpoint_sync" || task === "fastlane_sync" || task === "sync_recent") {
    return "legacy_sync_recent"
  }
  if (task === "branch_commit_backfill" || task === "sync_branch_history") {
    return "legacy_sync_branch_history"
  }
  return task
}

function toReconcileTriggerReason(reason: RepoSyncMessage["reason"]): ReconcileTriggerReason {
  if (reason === "drift" || reason === "failure" || reason === "audit" || reason === "manual") {
    return reason
  }
  return reason === "reconciliation" ? "periodic" : "manual"
}

// Log with consistent prefix
function log(event: string, data: Record<string, unknown>): void {
  console.log(`[repo-sync-queue] ${event}`, JSON.stringify(data))
}

function repoCommitToCheckpointPayloadCommit(commit: RepoCommitData): CheckpointPayloadCommit {
  return {
    sha: commit.commit_sha,
    message: commit.commit_message,
    author: {
      name: commit.commit_author,
      username: commit.commit_author_username,
      email: commit.commit_author_email ?? null,
    },
    timestamp: commit.commit_date,
    url: commit.html_url ?? null,
    parentShas: commit.parent_shas ?? [],
  }
}

type ProcessCheckpointPayloadFields = Pick<
  RepoSyncMessage,
  "checkpointPayloadCommits" | "checkpointShas"
>

function isLegacyCheckpointPayloadMessage(
  message: ProcessCheckpointPayloadFields,
): message is Pick<LegacyProcessCheckpointsPayloadMessage, "checkpointPayloadCommits"> {
  return Array.isArray(message.checkpointPayloadCommits)
}

function isCheckpointShaMessage(
  message: ProcessCheckpointPayloadFields,
): message is Pick<ProcessCheckpointsByShaMessage, "checkpointShas"> {
  return Array.isArray(message.checkpointShas)
}

async function hydrateCheckpointCommitsFromShas(
  db: Db,
  repoId: string,
  checkpointShas: string[],
): Promise<CheckpointPayloadCommit[]> {
  const rows = await db.checkpoints.getRepoCommitsByShas(repoId, checkpointShas)
  const rowsBySha = new Map(rows.map((commit) => [commit.commit_sha, commit]))
  const commits = checkpointShas
    .map((sha) => rowsBySha.get(sha))
    .filter((commit): commit is RepoCommitData => commit !== undefined)

  if (commits.length !== checkpointShas.length) {
    const missingShas = checkpointShas.filter((sha) => !rowsBySha.has(sha))
    log("checkpoint_commit_hydration_missing", {
      repoId,
      requested: checkpointShas.length,
      found: commits.length,
      missingShas: missingShas.slice(0, 20),
    })
    throw new Error(
      `Missing checkpoint commit rows for ${missingShas.length}/${checkpointShas.length} shas`,
    )
  }

  return commits.map(repoCommitToCheckpointPayloadCommit)
}

async function resolveProcessCheckpointCommits(
  db: Db,
  repoId: string,
  message: ProcessCheckpointPayloadFields,
): Promise<CheckpointPayloadCommit[] | null> {
  if (isLegacyCheckpointPayloadMessage(message)) {
    return message.checkpointPayloadCommits
  }
  if (isCheckpointShaMessage(message)) {
    return await hydrateCheckpointCommitsFromShas(db, repoId, message.checkpointShas)
  }
  return null
}

// KV key for per-installation rate limit state
function rateLimitKey(installationId: number): string {
  return `github:ratelimit:installation:${installationId}:resetAt`
}

// Check if a specific installation is currently rate limited
async function isRateLimited(cache: KVNamespace, installationId: number): Promise<boolean> {
  const key = rateLimitKey(installationId)
  const resetAt = await cache.get(key)
  if (!resetAt) return false

  const resetTime = parseInt(resetAt, 10)
  if (Date.now() < resetTime) {
    return true
  }

  // Rate limit has expired, clean up
  await cache.delete(key)
  return false
}

// Set rate limit marker for a specific installation (called when we hit a rate limit)
async function setRateLimitMarker(
  cache: KVNamespace,
  installationId: number,
  resetAt?: number,
): Promise<void> {
  // Default to 15 minutes from now if no reset time provided
  const resetTime = resetAt ?? Date.now() + 15 * 60 * 1000
  // Store with TTL of 1 hour (self-cleaning)
  await cache.put(rateLimitKey(installationId), String(resetTime), {
    expirationTtl: 60 * 60,
  })
  log("rate_limit_set", { installationId, resetAt: new Date(resetTime).toISOString() })
}

