// Look up the GitHub App installation ID for a repo
async function getRepoInstallationId(db: Db, repoId: string): Promise<number | null> {
  const repo = await db.repos.getById(repoId)

  if (!repo) {
    log("repo_not_found", { repoId })
    return null
  }

  // Fast path: use the direct FK if available
  if (repo.installation_id) {
    const githubInstallationId = await db.installations.getGithubId(repo.installation_id)
    if (githubInstallationId) {
      return githubInstallationId
    }
  }

  // NB: This fallback shouldn't be required for long.
  // Fallback: look up by owner name (for repos not yet backfilled)
  const owner = repo.full_name.split("/")[0]
  const githubInstallationId = await db.installations.getGithubIdByOwner(owner)
  if (!githubInstallationId) {
    log("no_installation_for_repo", { repoId, owner })
    return null
  }

  return githubInstallationId
}

// Get a valid token for a GitHub App installation
async function getTokenForInstallation(installationId: number, env: Env): Promise<string | null> {
  try {
    return await getInstallationToken(
      installationId,
      {
        appId: env.GITHUB_CLIENT_ID,
        privateKey: env.GITHUB_APP_PRIVATE_KEY,
      },
      env.ENTIRE_CACHE,
    )
  } catch (err) {
    log("installation_token_error", {
      installationId,
      error: errorString(err),
    })
    return null
  }
}

type QueueTaskResult = {
  status: "ok" | "skipped" | "error"
  reason?: string
  discoveredCheckpointIds?: string[]
  checkpointsDiscovered?: number
  [key: string]: unknown
}

async function getTokenForRepoTask(
  env: Env,
  db: Db,
  batchId: string,
  repoId: string,
  reason: RepoSyncMessage["reason"],
): Promise<{ token: string; installationId: number } | { result: QueueTaskResult }> {
  const installationId = await getRepoInstallationId(db, repoId)
  if (!installationId) {
    log("no_installation_for_repo", { batchId, repoId, reason })
    return { result: { status: "skipped", reason: "no_installation_for_repo" } }
  }

  if (await isRateLimited(env.ENTIRE_CACHE, installationId)) {
    log("message_skipped_rate_limited", { batchId, repoId, installationId, reason })
    return { result: { status: "skipped", reason: "rate_limited", retry: true } }
  }

  const token = await getTokenForInstallation(installationId, env)
  if (!token) {
    log("no_token_for_repo", { batchId, repoId, installationId, reason })
    return { result: { status: "skipped", reason: "no_token_for_repo" } }
  }

  return { token, installationId }
}

function isRepoSyncDenylisted(env: Env, fullName: string | null | undefined): boolean {
  if (!fullName || !env.REPO_SYNC_DENYLIST) return false
  const target = fullName.toLowerCase()
  return env.REPO_SYNC_DENYLIST.split(",").some((entry) => entry.trim().toLowerCase() === target)
}

const REPO_SYNC_TIMED_OUT = Symbol("repo_sync_message_timeout")

function repoSyncMessageTimeoutMs(env: Env): number {
  const raw = env.REPO_SYNC_MESSAGE_TIMEOUT_MS
  if (raw === undefined || raw === "") return 30_000
  const parsed = Number(raw)
  return Number.isFinite(parsed) && parsed > 0 ? parsed : 0
}

function repoSyncDlqTasks(env: Env): Set<string> {
  if (!env.REPO_SYNC_DLQ_TASKS) return new Set()
  return new Set(
    env.REPO_SYNC_DLQ_TASKS.split(",")
      .map((t) => t.trim())
      .filter(Boolean),
  )
}

