type ScrollAnchor = { id: string; offset: number }

/**
 * Call right before a state change that reflows the timeline. Snapshots an
 * ordered list of entries currently anchored near the top of the viewport;
 * after React commits, scrolls the first surviving anchor back to its
 * original offset so the user keeps their place.
 *
 * Two subtleties drive the multi-anchor list:
 *   - The primary anchor may be filtered out by the same toggle (a checkpoint
 *     row when Checkpoints is hidden, a tool-call row when Tool calls is
 *     hidden). Fallbacks let the next visible entry take over.
 *   - When a message bubble contains inline tool-call rows, the outer
 *     `timeline-${msg}` is a DOM ancestor of `timeline-${tool}`. The outer's `top`
 *     doesn't move when its interior reflows, so anchoring to it produces
 *     delta=0 even though the viewport's actual content shifted. The capture
 *     pass prefers entries below the header (offset >= 0) so interior leaves
 *     win over their containers.
 */
function usePreserveTimelineScroll(containerRef: RefObject<HTMLElement | null>): () => void {
  const stateRef = useRef<{ anchors: ScrollAnchor[]; header: number } | null>(null)
  const [token, setToken] = useState(0)

  useLayoutEffect(() => {
    const state = stateRef.current
    if (!state) return
    stateRef.current = null
    for (const { id, offset } of state.anchors) {
      const el = document.getElementById(id)
      if (!el) continue
      const delta = el.getBoundingClientRect().top - state.header - offset
      if (delta !== 0) window.scrollBy({ top: delta, behavior: "instant" })
      return
    }
  }, [token])

  return useCallback(() => {
    const container = containerRef.current
    if (!container) return
    const header = getHeaderOffset()
    const visible: ScrollAnchor[] = []
    for (const el of container.querySelectorAll<HTMLElement>('[id^="timeline-"]')) {
      const rect = el.getBoundingClientRect()
      if (rect.bottom <= header) continue
      visible.push({ id: el.id, offset: rect.top - header })
    }
    if (visible.length === 0) return
    // Entries below the header (positive offset) first, nearest the header
    // ahead; containers spanning the header (negative offset) last, as a
    // fallback only.
    visible.sort((a, b) => {
      const aBelow = a.offset >= 0
      const bBelow = b.offset >= 0
      if (aBelow !== bBelow) return aBelow ? -1 : 1
      return a.offset - b.offset
    })
    stateRef.current = { anchors: visible.slice(0, 8), header }
    setToken((n) => n + 1)
  }, [containerRef])
}

/**
 * Compact duration between two ISO timestamps. Sub-minute durations show one decimal
 * second ("14.3s"), minute durations drop the seconds ("13m"), and multi-hour ones
 * stay terse ("1h 30m"). Returns null for zero or invalid ranges.
 */
function formatCompactDuration(startIso: string, endIso: string): string | null {
  const ms = new Date(endIso).getTime() - new Date(startIso).getTime()
  if (!Number.isFinite(ms) || ms <= 0) return null
  const seconds = ms / 1000
  if (seconds < 60) return `${seconds.toFixed(1)}s`
  const mins = Math.round(seconds / 60)
  if (mins < 60) return `${mins}m`
  const hours = Math.floor(mins / 60)
  const remMin = mins % 60
  return remMin > 0 ? `${hours}h ${remMin}m` : `${hours}h`
}

