export async function checkRepoAccess(
  db: Db,
  repoFullName: string,
  userId: string | undefined,
  options: { requireRepo?: boolean } = {},
): Promise<RepoRecord | null | Response> {
  if (userId) {
    // Authenticated: check user_repos join (existing behavior)
    const result = await db.repos.getByFullNameWithAccess(repoFullName, userId)

    if (result.status === "found") {
      return result.repo
    }

    if (result.status === "not_found") {
      if (options.requireRepo) {
        return new Response(JSON.stringify({ error: "Repository not found" }), {
          status: 404,
          headers: { "Content-Type": "application/json" },
        })
      }
      return null
    }

    // status === "no_access"
    // Fall back to public repo access for authenticated users too.
    // This ensures signed-in users can view public repos they don't explicitly own.
    const publicRepo = await db.repos.getPublicByFullName(repoFullName)
    if (publicRepo) return publicRepo

    // Private repo with no access: return 404 to prevent repo fishing.
    return new Response(JSON.stringify({ error: "Repository not found" }), {
      status: 404,
      headers: { "Content-Type": "application/json" },
    })
  }

  // Unauthenticated: only serve public repos (hardcoded is_private = false)
  const repo = await db.repos.getPublicByFullName(repoFullName)
  if (!repo) {
    if (options.requireRepo) {
      return new Response(JSON.stringify({ error: "Repository not found" }), {
        status: 404,
        headers: { "Content-Type": "application/json" },
      })
    }
    return null
  }
  return repo
}

