import { createFileRoute, notFound } from "@tanstack/react-router"
import { useCallback } from "react"

import { redirectToLogin, shouldRedirectToLogin } from "@/domains/platform/auth/loginRedirect"
import { sessionTranscriptQueryOptions } from "@/domains/platform/checkpoints/hooks/useCommitsQuery"
import { Page } from "@/domains/platform/components/Page"
import { SessionDetailSkeleton } from "@/domains/platform/sessions/components/SessionTimelineView"
import { SessionDetailPage } from "@/domains/platform/sessions/pages/SessionDetailPage"
import { ApiError } from "@/lib/api"

export const Route = createFileRoute("/_app/_repo/gh/$org/$repo/session/$sessionId")({
  loader: async ({ context, params, location }) => {
    try {
      await context.queryClient.ensureQueryData(
        sessionTranscriptQueryOptions(params.org, params.repo, params.sessionId),
      )
    } catch (error) {
      if (shouldRedirectToLogin({ auth: context.auth, error })) {
        throw redirectToLogin({ location })
      }

      if (error instanceof ApiError && error.status === 404) {
        throw notFound()
      }

      throw error
    }
  },
  component: SessionDetailPageRoute,
  pendingComponent: SessionDetailPending,
})

function SessionDetailPending() {
  return (
    <Page>
      <SessionDetailSkeleton />
    </Page>
  )
}

function SessionDetailPageRoute() {
  const params = Route.useParams() as { org: string; repo: string; sessionId: string }
  const navigate = Route.useNavigate()
  const handleTimelineTargetChange = useCallback(
    (targetId: string | null) => {
      void navigate({
        replace: true,
        hash: targetId ? `timeline-${targetId}` : undefined,
      })
    },
    [navigate],
  )
  return (
    <SessionDetailPage
      org={params.org}
      repo={params.repo}
      sessionId={params.sessionId}
      onTimelineTargetChange={handleTimelineTargetChange}
    />
  )
}

