    const org = requiredParam(c, "org")
    const repo = requiredParam(c, "repo")
    const sessionId = requiredParam(c, "sessionId")
    const repoFullName = `${org}/${repo}`

    if (!SESSION_ID_PATTERN.test(sessionId)) {
      return c.json({ error: "Invalid session ID format" }, 400)
    }

    const db = getDb(c.env)

    const access = await resolveSessionAccess(c, db, { repoFullName, sessionId, userId })
    if (access instanceof Response) return access
    const { repo: repoAccess, mode, isShared } = access

    const viewerCanSeeCheckpointData = await hasCheckpointDataAccess(db, repoAccess, userId)

    // Storage-repo gate, with an explicit shared-session bypass: a session-share
    // row is the deliberate access grant from someone with storage membership
    // (POST /share enforces that), so honoring it here is what makes share
    // links work across the storage-repo ACL.
    if (!isShared && !viewerCanSeeCheckpointData) {
      return c.json({ error: CHECKPOINT_REPO_ACCESS_DENIED_ERROR }, 403)
    }

    const shareToggleApplicable = await isShareToggleApplicable(db, repoAccess)

    // Cache is shape-versioned: bumped to v2 when the response grew to include
    // envelope metadata. Old entries expire via their original TTL.
    const cacheKey = buildSessionTranscriptCacheKey(repoFullName, sessionId)
    const cachedCore = await c.env.ENTIRE_CACHE.get<SessionTranscriptCoreCacheEntry>(
      cacheKey,
      "json",
    )
    if (cachedCore) {
      const repoSession = await getMaterialisedSessionForTranscript(db, repoAccess.id, sessionId)
      const responseCore = withMaterialisedSessionMeta(cachedCore, repoSession)
      return c.json({
        status: "complete",
        ...buildSessionResponseMeta(
          repoAccess,
          mode,
          isShared,
          shareToggleApplicable,
          viewerCanSeeCheckpointData,
          responseCore,
        ),
        sessionId,
        sessions: cachedCore.sessions,
        from_cache: true,
      })
    }

    try {
      // `getForSession` queries by sessionId across all branches, so session
      // detail stays branch-agnostic.
      const checkpoints = await db.checkpoints.getForSession(repoAccess.id, sessionId)

      if (checkpoints.length === 0) {
        // Debounce: a recently-run self-heal for this (repo, session) means a
        // hydration is already in flight, so skip the redundant backlog scan +
        // re-scheduling and just tell the client to keep polling. getForSession
        // above still runs every poll, so a completed hydration is served
        // without waiting the window out.
        const selfHealGuardKey = `session-transcript-heal:${repoAccess.id}:${sessionId}`
        if ((await c.env.ENTIRE_CACHE.get(selfHealGuardKey)) !== null) {
          console.log(
            `[transcript-self-heal] skipped repo=${repoAccess.full_name} sessionId=${sessionId} reason=debounced`,
          )
          return c.json({ status: "pending", sessionId })
        }

