            : undefined,
        )
        console.log(
          `[transcript-self-heal] decided repo=${repoAccess.full_name} sessionId=${sessionId} ` +
            `bounded=${sessionIsCheckpointId} backlog=${missingSessionCheckpointIds.length} ` +
            `action=${missingSessionCheckpointIds.length > 0 ? "scheduled" : "not_found"}`,
        )
        if (missingSessionCheckpointIds.length > 0) {
          await scheduleCheckpointHydration(c, db, repoAccess, missingSessionCheckpointIds, userId)
          await c.env.ENTIRE_CACHE.put(selfHealGuardKey, "1", {
            expirationTtl: SELF_HEAL_DEBOUNCE_TTL_SECONDS,
          })
          return c.json({ status: "pending", sessionId })
        }
        return c.json({ error: "Not found" }, 404)
      }

      const missingPayloadCheckpointIds = checkpoints
        .filter(
          (checkpoint) =>
            checkpoint.payload_hydration_state !== "complete" &&
            checkpoint.payload_hydration_state !== "complete_empty" &&
            checkpoint.payload_hydration_state !== "error",
