      const tokenUsage: SessionTranscript["tokenUsage"] | undefined = merged.tokenUsage
      const attribution: SessionAttribution | undefined = merged.attribution

      const sessions: SessionTranscript[] =
        mergedMessages.length > 0
          ? [
              {
                sessionId,
                agent: sessionAgent,
                messages: mergedMessages,
                transcriptIdentifierAtStart: null,
                checkpointTranscriptStart: null,
                tokenUsage,
                attribution,
                skillEvents: merged.skillEvents,
              },
