      // model, agent, steps, createdAt). Scoping-safe: only entries where
      // `sessionId === sessionId` are read, so sibling sessions on the same
      // checkpoint never leak into the response.
      const envelopeMeta = extractSessionEnvelopeMeta(checkpoints, merged, sessionId)

