      const responseCore = withMaterialisedSessionMeta(core, repoSession)

      // Only persist non-empty responses — an empty array is usually a transient
      // miss (DB not yet populated, GitHub fetch failed, etc.) and caching it
      // would poison subsequent reads for the full TTL.
      if (sessions.length > 0) {
