        } catch (cacheErr) {
          console.warn(`Session transcript cache write failed for ${cacheKey}:`, cacheErr)
        }
      }

      return c.json({
        status: "complete",
        ...buildSessionResponseMeta(
          repoAccess,
          mode,
          isShared,
          shareToggleApplicable,
          viewerCanSeeCheckpointData,
          responseCore,
        ),
        sessionId,
        sessions,
        from_cache: false,

