export function createCheckpointTimelineEvents(
  checkpoints: TrailCheckpointSummary[],
  existingCommitShas: Set<string> = new Set(),
): TrailTimelineEvent[] {
  const checkpointsByCommit = new Map<string, TrailCheckpointSummary[]>()

  for (const checkpoint of checkpoints) {
    if (checkpoint.commitSha && existingCommitShas.has(checkpoint.commitSha)) continue
    const key = checkpoint.commitSha ?? checkpoint.checkpointId
    checkpointsByCommit.set(key, [...(checkpointsByCommit.get(key) ?? []), checkpoint])
  }

  return Array.from(checkpointsByCommit.entries()).map(([key, group]) => {
    const checkpoint = group[0]
    const sessionCount = group.reduce((count, item) => count + item.sessionCount, 0)
    const agents = Array.from(new Set(group.flatMap((item) => item.agents).filter(Boolean)))

    return {
      id: `checkpoint-commit-${key}`,
      kind: "commit" as const,
      title:
        checkpoint.commitSubject ||
        checkpoint.commitMessage ||
        `Checkpoint ${checkpoint.checkpointId.slice(0, 7)}`,
      actor: checkpoint.commitAuthorUsername
        ? { login: checkpoint.commitAuthorUsername }
        : checkpoint.commitAuthor
          ? { label: checkpoint.commitAuthor }
          : null,
      commitSha: checkpoint.commitSha ?? checkpoint.checkpointId,
      additions: checkpoint.additions,
      deletions: checkpoint.deletions,
      filesChanged: checkpoint.filesChanged,
      checkpointCount: group.length,
      sessionCount,
      agents,
      isLinkable: Boolean(checkpoint.commitSha),
      occurredAt: checkpoint.commitDate,
    }
  })
}

