		if cleanPath == cleanFile {
			return true
		}
	}

	for _, dir := range agent.AllProtectedDirs() {
		cleanDir := filepath.Clean(filepath.FromSlash(dir))
		if paths.IsSubpath(cleanDir, cleanPath) {
			return true
		}
	}

